INSERT INTO `snmp_mib`(`id`, `name`, `file_name`, `content`, `models`, `remark`, `update_by`, `update_at`, `tree`) VALUES (1, 'AGENTX-MIB', 'AGENTX-MIB.txt', , '1,2', '', 1, '2021-09-29 11:55:20', '{\"AGENTX-MIB\":[{\"index\":[],\"name\":\"agentxMIB\",\"objectID\":\"1.3.6.1.2.1.74\",\"pid\":\"1.3.6.1.2.1\",\"subTree\":[{\"index\":[],\"name\":\"agentxObjects\",\"objectID\":\"1.3.6.1.2.1.74.1\",\"pid\":\"1.3.6.1.2.1.74\",\"subTree\":[{\"index\":[],\"name\":\"agentxGeneral\",\"objectID\":\"1.3.6.1.2.1.74.1.1\",\"pid\":\"1.3.6.1.2.1.74.1\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The default length of time, in seconds, that the master\\nagent should allow to elapse after dispatching a message\\nto a session before it regards the subagent as not\\nresponding.  This is a system-wide value that may\\noverride the timeout value associated with a particular\\nsession (agentxSessionTimeout) or a particular registered\\nMIB region (agentxRegTimeout).  If the associated value of\\nagentxSessionTimeout and agentxRegTimeout are zero, or\\nimpractical in accordance with implementation-specific\\nprocedure of the master agent, the value represented by\\nthis object will be the effective timeout value for the\\n\\nmaster agent to await a response to a dispatch from a\\ngiven subagent.\\n\",\"index\":[],\"name\":\"agentxDefaultTimeout\",\"objectID\":\"1.3.6.1.2.1.74.1.1.1\",\"pid\":\"1.3.6.1.2.1.74.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The AgentX protocol version supported by this master agent.\\nThe current protocol version is 1.  Note that the master agent\\nmust also allow interaction with earlier version subagents.\\n\",\"index\":[],\"name\":\"agentxMasterAgentXVer\",\"objectID\":\"1.3.6.1.2.1.74.1.1.2\",\"pid\":\"1.3.6.1.2.1.74.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"agentxConnection\",\"objectID\":\"1.3.6.1.2.1.74.1.2\",\"pid\":\"1.3.6.1.2.1.74.1\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The value of sysUpTime when the last row creation or deletion\\noccurred in the agentxConnectionTable.\\n\",\"index\":[],\"name\":\"agentxConnTableLastChange\",\"objectID\":\"1.3.6.1.2.1.74.1.2.1\",\"pid\":\"1.3.6.1.2.1.74.1.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"The agentxConnectionTable tracks all current AgentX transport\\nconnections.  There may be zero, one, or more AgentX sessions\\ncarried on a given AgentX connection.\\n\",\"index\":[],\"name\":\"agentxConnectionTable\",\"objectID\":\"1.3.6.1.2.1.74.1.2.2\",\"pid\":\"1.3.6.1.2.1.74.1.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"An agentxConnectionEntry contains information describing a\\nsingle AgentX transport connection.  A connection may be\\n\\nused to support zero or more AgentX sessions.  An entry is\\ncreated when a new transport connection is established,\\nand is destroyed when the transport connection is terminated.\\n\",\"index\":[\"1.3.6.1.2.1.74.1.2.2.1.1\"],\"name\":\"agentxConnectionEntry\",\"objectID\":\"1.3.6.1.2.1.74.1.2.2.1\",\"pid\":\"1.3.6.1.2.1.74.1.2.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"agentxConnIndex contains the value that uniquely identifies\\nan open transport connection used by this master agent\\nto provide AgentX service.  Values of this index should\\nnot be re-used.  The value assigned to a given transport\\nconnection is constant for the lifetime of that connection.\\n\",\"index\":[],\"name\":\"agentxConnIndex\",\"objectID\":\"1.3.6.1.2.1.74.1.2.2.1.1\",\"pid\":\"1.3.6.1.2.1.74.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The value of sysUpTime when this connection was established\\nand, therefore, its value when this entry was added to the table.\\n\",\"index\":[],\"name\":\"agentxConnOpenTime\",\"objectID\":\"1.3.6.1.2.1.74.1.2.2.1.2\",\"pid\":\"1.3.6.1.2.1.74.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The transport protocol in use for this connection to the\\nsubagent.\\n\",\"index\":[],\"name\":\"agentxConnTransportDomain\",\"objectID\":\"1.3.6.1.2.1.74.1.2.2.1.3\",\"pid\":\"1.3.6.1.2.1.74.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The transport address of the remote (subagent) end of this\\nconnection to the master agent.  This object may be zero-length\\nfor unix-domain sockets (and possibly other types of transport\\naddresses) since the subagent need not bind a filename to its\\nlocal socket.\\n\",\"index\":[],\"name\":\"agentxConnTransportAddress\",\"objectID\":\"1.3.6.1.2.1.74.1.2.2.1.4\",\"pid\":\"1.3.6.1.2.1.74.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"agentxSession\",\"objectID\":\"1.3.6.1.2.1.74.1.3\",\"pid\":\"1.3.6.1.2.1.74.1\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The value of sysUpTime when the last row creation or deletion\\noccurred in the agentxSessionTable.\\n\",\"index\":[],\"name\":\"agentxSessionTableLastChange\",\"objectID\":\"1.3.6.1.2.1.74.1.3.1\",\"pid\":\"1.3.6.1.2.1.74.1.3\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A table of AgentX subagent sessions currently in effect.\\n\",\"index\":[],\"name\":\"agentxSessionTable\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2\",\"pid\":\"1.3.6.1.2.1.74.1.3\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information about a single open session between the AgentX\\nmaster agent and a subagent is contained in this entry.  An\\nentry is created when a new session is successfully established\\nand is destroyed either when the subagent transport connection\\nhas terminated or when the subagent session is closed.\\n\",\"index\":[\"1.3.6.1.2.1.74.1.2.2.1.1\",\"1.3.6.1.2.1.74.1.3.2.1.1\"],\"name\":\"agentxSessionEntry\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1\",\"pid\":\"1.3.6.1.2.1.74.1.3.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A unique index for the subagent session.  It is the same as\\nh.sessionID defined in the agentx header.  Note that if\\na subagent\'s session with the master agent is closed for\\nany reason its index should not be re-used.\\nA value of zero(0) is specifically allowed in order\\nto be compatible with the definition of h.sessionId.\\n\",\"index\":[],\"name\":\"agentxSessionIndex\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.1\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This is taken from the o.id field of the agentx-Open-PDU.\\nThis attribute will report a value of \'0.0\' for subagents\\nnot supporting the notion of an AgentX session object\\nidentifier.\\n\",\"index\":[],\"name\":\"agentxSessionObjectID\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.2\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"A textual description of the session.  This is analogous to\\nsysDescr defined in the SNMPv2-MIB in RFC 1907 [19] and is\\ntaken from the o.descr field of the agentx-Open-PDU.\\nThis attribute will report a zero-length string value for\\nsubagents not supporting the notion of a session description.\\n\",\"index\":[],\"name\":\"agentxSessionDescr\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.3\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The administrative (desired) status of the session.  Setting\\nthe value to \'down(2)\' closes the subagent session (with c.reason\\nset to \'reasonByManager\').\\n\",\"index\":[],\"name\":\"agentxSessionAdminStatus\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.4\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The value of sysUpTime when this session was opened and,\\ntherefore, its value when this entry was added to the table.\\n\",\"index\":[],\"name\":\"agentxSessionOpenTime\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.5\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The version of the AgentX protocol supported by the\\nsession.  This must be less than or equal to the value of\\nagentxMasterAgentXVer.\\n\",\"index\":[],\"name\":\"agentxSessionAgentXVer\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.6\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The length of time, in seconds, that a master agent should\\nallow to elapse after dispatching a message to this session\\nbefore it regards the subagent as not responding.  This value\\nis taken from the o.timeout field of the agentx-Open-PDU.\\nThis is a session-specific value that may be overridden by\\nvalues associated with the specific registered MIB regions\\n(see agentxRegTimeout). A value of zero(0) indicates that\\nthe master agent\'s default timeout value should be used\\n\\n(see agentxDefaultTimeout).\\n\",\"index\":[],\"name\":\"agentxSessionTimeout\",\"objectID\":\"1.3.6.1.2.1.74.1.3.2.1.7\",\"pid\":\"1.3.6.1.2.1.74.1.3.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"agentxRegistration\",\"objectID\":\"1.3.6.1.2.1.74.1.4\",\"pid\":\"1.3.6.1.2.1.74.1\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The value of sysUpTime when the last row creation or deletion\\noccurred in the agentxRegistrationTable.\\n\",\"index\":[],\"name\":\"agentxRegistrationTableLastChange\",\"objectID\":\"1.3.6.1.2.1.74.1.4.1\",\"pid\":\"1.3.6.1.2.1.74.1.4\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A table of registered regions.\\n\",\"index\":[],\"name\":\"agentxRegistrationTable\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2\",\"pid\":\"1.3.6.1.2.1.74.1.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Contains information for a single registered region.  An\\nentry is created when a session  successfully registers a\\nregion and is destroyed for any of three reasons: this region\\nis unregistered by the session, the session is closed,\\nor the subagent connection is closed.\\n\",\"index\":[\"1.3.6.1.2.1.74.1.2.2.1.1\",\"1.3.6.1.2.1.74.1.3.2.1.1\",\"1.3.6.1.2.1.74.1.4.2.1.1\"],\"name\":\"agentxRegistrationEntry\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1\",\"pid\":\"1.3.6.1.2.1.74.1.4.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"agentxRegIndex uniquely identifies a registration entry.\\nThis value is constant for the lifetime of an entry.\\n\",\"index\":[],\"name\":\"agentxRegIndex\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.1\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The context in which the session supports the objects in this\\nregion.  A zero-length context indicates the default context.\\n\",\"index\":[],\"name\":\"agentxRegContext\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.2\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The starting OBJECT IDENTIFIER of this registration entry.  The\\nsession identified by agentxSessionIndex implements objects\\nstarting at this value (inclusive).  Note that this value could\\nidentify an object type, an object instance, or a partial object\\ninstance.\\n\",\"index\":[],\"name\":\"agentxRegStart\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.3\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"agentxRegRangeSubId is used to specify the range.  This is\\ntaken from r.region_subid in the registration PDU.  If the value\\nof this object is zero, no range is specified.  If it is non-zero,\\nit identifies the `nth\' sub-identifier in r.region for which\\nthis entry\'s agentxRegUpperBound value is substituted in the\\nOID for purposes of defining the region\'s upper bound.\\n\",\"index\":[],\"name\":\"agentxRegRangeSubId\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.4\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"agentxRegUpperBound represents the upper-bound sub-identifier in\\na registration.  This is taken from the r.upper_bound in the\\nregistration PDU.  If agentxRegRangeSubid (r.region_subid) is\\nzero, this value is also zero and is not used to define an upper\\nbound for this registration.\\n\",\"index\":[],\"name\":\"agentxRegUpperBound\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.5\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The registration priority.  Lower values have higher priority.\\nThis value is taken from r.priority in the register PDU.\\nSessions should use the value of 127 for r.priority if a\\ndefault value is desired.\\n\",\"index\":[],\"name\":\"agentxRegPriority\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.6\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The timeout value, in seconds, for responses to\\nrequests associated with this registered MIB region.\\nA value of zero(0) indicates the default value (indicated\\nby by agentxSessionTimeout or agentxDefaultTimeout) is to\\nbe used.  This value is taken from the r.timeout field of\\nthe agentx-Register-PDU.\\n\",\"index\":[],\"name\":\"agentxRegTimeout\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.7\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The value of agentxRegInstance is `true\' for\\nregistrations for which the INSTANCE_REGISTRATION\\nwas set, and is `false\' for all other registrations.\\n\",\"index\":[],\"name\":\"agentxRegInstance\",\"objectID\":\"1.3.6.1.2.1.74.1.4.2.1.8\",\"pid\":\"1.3.6.1.2.1.74.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"}],\"type\":\"IDENTIFIER\"},{\"access\":\"read-only\",\"description\":\"The value of agentxRegInstance is `true\' for\\nregistrations for which the INSTANCE_REGISTRATION\\nwas set, and is `false\' for all other registrations.\\n\",\"index\":[],\"name\":\"agentxConformance\",\"objectID\":\"1.3.6.1.2.1.74.2\",\"pid\":\"1.3.6.1.2.1.74\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The value of agentxRegInstance is `true\' for\\nregistrations for which the INSTANCE_REGISTRATION\\nwas set, and is `false\' for all other registrations.\\n\",\"index\":[],\"name\":\"agentxMIBGroups\",\"objectID\":\"1.3.6.1.2.1.74.2.1\",\"pid\":\"1.3.6.1.2.1.74.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The value of agentxRegInstance is `true\' for\\nregistrations for which the INSTANCE_REGISTRATION\\nwas set, and is `false\' for all other registrations.\\n\",\"index\":[],\"name\":\"agentxMIBGroup\",\"objectID\":\"1.3.6.1.2.1.74.2.1.1\",\"pid\":\"1.3.6.1.2.1.74.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"},{\"access\":\"read-only\",\"description\":\"The value of agentxRegInstance is `true\' for\\nregistrations for which the INSTANCE_REGISTRATION\\nwas set, and is `false\' for all other registrations.\\n\",\"index\":[],\"name\":\"agentxMIBCompliances\",\"objectID\":\"1.3.6.1.2.1.74.2.2\",\"pid\":\"1.3.6.1.2.1.74.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The value of agentxRegInstance is `true\' for\\nregistrations for which the INSTANCE_REGISTRATION\\nwas set, and is `false\' for all other registrations.\\n\",\"index\":[],\"name\":\"agentxMIBCompliance\",\"objectID\":\"1.3.6.1.2.1.74.2.2.1\",\"pid\":\"1.3.6.1.2.1.74.2.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"type\":\"OBJECT\"}]}');
INSERT INTO `snmp_mib`(`id`, `name`, `file_name`, `content`, `models`, `remark`, `update_by`, `update_at`, `tree`) VALUES (2, 'BRIDGE-MIB', 'BRIDGE-MIB.txt', , '', '', 1, '2021-09-29 11:55:30', '{\"BRIDGE-MIB\":[{\"index\":[],\"name\":\"dot1dBridge\",\"objectID\":\"1.3.6.1.2.1.17\",\"pid\":\"1.3.6.1.2.1\",\"subTree\":[{\"index\":[],\"name\":\"dot1dNotifications\",\"objectID\":\"1.3.6.1.2.1.17.0\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"newRoot\",\"objectID\":\"1.3.6.1.2.1.17.0.1\",\"pid\":\"1.3.6.1.2.1.17.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"topologyChange\",\"objectID\":\"1.3.6.1.2.1.17.0.2\",\"pid\":\"1.3.6.1.2.1.17.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"dot1dBase\",\"objectID\":\"1.3.6.1.2.1.17.1\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The MAC address used by this bridge when it must be\\nreferred to in a unique fashion.  It is recommended\\nthat this be the numerically smallest MAC address of\\nall ports that belong to this bridge.  However, it is only\\n\\nrequired to be unique.  When concatenated with\\ndot1dStpPriority, a unique BridgeIdentifier is formed,\\nwhich is used in the Spanning Tree Protocol.\",\"index\":[],\"name\":\"dot1dBaseBridgeAddress\",\"objectID\":\"1.3.6.1.2.1.17.1.1\",\"pid\":\"1.3.6.1.2.1.17.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of ports controlled by this bridging\\nentity.\",\"index\":[],\"name\":\"dot1dBaseNumPorts\",\"objectID\":\"1.3.6.1.2.1.17.1.2\",\"pid\":\"1.3.6.1.2.1.17.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Indicates what type of bridging this bridge can\\nperform.  If a bridge is actually performing a\\ncertain type of bridging, this will be indicated by\\nentries in the port table for the given type.\",\"index\":[],\"name\":\"dot1dBaseType\",\"objectID\":\"1.3.6.1.2.1.17.1.3\",\"pid\":\"1.3.6.1.2.1.17.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A table that contains generic information about every\\nport that is associated with this bridge.  Transparent,\\nsource-route, and srt ports are included.\",\"index\":[],\"name\":\"dot1dBasePortTable\",\"objectID\":\"1.3.6.1.2.1.17.1.4\",\"pid\":\"1.3.6.1.2.1.17.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A list of information for each port of the bridge.\",\"index\":[\"1.3.6.1.2.1.17.1.4.1.1\"],\"name\":\"dot1dBasePortEntry\",\"objectID\":\"1.3.6.1.2.1.17.1.4.1\",\"pid\":\"1.3.6.1.2.1.17.1.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The port number of the port for which this entry\\ncontains bridge management information.\",\"index\":[],\"name\":\"dot1dBasePort\",\"objectID\":\"1.3.6.1.2.1.17.1.4.1.1\",\"pid\":\"1.3.6.1.2.1.17.1.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The value of the instance of the ifIndex object,\\ndefined in IF-MIB, for the interface corresponding\\nto this port.\",\"index\":[],\"name\":\"dot1dBasePortIfIndex\",\"objectID\":\"1.3.6.1.2.1.17.1.4.1.2\",\"pid\":\"1.3.6.1.2.1.17.1.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"For a port that (potentially) has the same value of\\ndot1dBasePortIfIndex as another port on the same bridge.\\nThis object contains the name of an object instance\\nunique to this port.  For example, in the case where\\nmultiple ports correspond one-to-one with multiple X.25\\nvirtual circuits, this value might identify an (e.g.,\\nthe first) object instance associated with the X.25\\nvirtual circuit corresponding to this port.\\n\\nFor a port which has a unique value of\\ndot1dBasePortIfIndex, this object can have the value\\n{ 0 0 }.\",\"index\":[],\"name\":\"dot1dBasePortCircuit\",\"objectID\":\"1.3.6.1.2.1.17.1.4.1.3\",\"pid\":\"1.3.6.1.2.1.17.1.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of frames discarded by this port due\\nto excessive transit delay through the bridge.  It\\nis incremented by both transparent and source\\nroute bridges.\",\"index\":[],\"name\":\"dot1dBasePortDelayExceededDiscards\",\"objectID\":\"1.3.6.1.2.1.17.1.4.1.4\",\"pid\":\"1.3.6.1.2.1.17.1.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of frames discarded by this port due\\nto an excessive size.  It is incremented by both\\ntransparent and source route bridges.\",\"index\":[],\"name\":\"dot1dBasePortMtuExceededDiscards\",\"objectID\":\"1.3.6.1.2.1.17.1.4.1.5\",\"pid\":\"1.3.6.1.2.1.17.1.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"dot1dStp\",\"objectID\":\"1.3.6.1.2.1.17.2\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"An indication of what version of the Spanning Tree\\nProtocol is being run.  The value \'decLb100(2)\'\\nindicates the DEC LANbridge 100 Spanning Tree protocol.\\nIEEE 802.1D implementations will return \'ieee8021d(3)\'.\\nIf future versions of the IEEE Spanning Tree Protocol\\nthat are incompatible with the current version\\nare released a new value will be defined.\",\"index\":[],\"name\":\"dot1dStpProtocolSpecification\",\"objectID\":\"1.3.6.1.2.1.17.2.1\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The value of the write-able portion of the Bridge ID\\n(i.e., the first two octets of the (8 octet long) Bridge\\nID).  The other (last) 6 octets of the Bridge ID are\\ngiven by the value of dot1dBaseBridgeAddress.\\nOn bridges supporting IEEE 802.1t or IEEE 802.1w,\\npermissible values are 0-61440, in steps of 4096.\",\"index\":[],\"name\":\"dot1dStpPriority\",\"objectID\":\"1.3.6.1.2.1.17.2.2\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The time (in hundredths of a second) since the\\nlast time a topology change was detected by the\\nbridge entity.\\nFor RSTP, this reports the time since the tcWhile\\ntimer for any port on this Bridge was nonzero.\",\"index\":[],\"name\":\"dot1dStpTimeSinceTopologyChange\",\"objectID\":\"1.3.6.1.2.1.17.2.3\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The total number of topology changes detected by\\nthis bridge since the management entity was last\\nreset or initialized.\",\"index\":[],\"name\":\"dot1dStpTopChanges\",\"objectID\":\"1.3.6.1.2.1.17.2.4\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The bridge identifier of the root of the spanning\\ntree, as determined by the Spanning Tree Protocol,\\nas executed by this node.  This value is used as\\nthe Root Identifier parameter in all Configuration\\nBridge PDUs originated by this node.\",\"index\":[],\"name\":\"dot1dStpDesignatedRoot\",\"objectID\":\"1.3.6.1.2.1.17.2.5\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The cost of the path to the root as seen from\\nthis bridge.\",\"index\":[],\"name\":\"dot1dStpRootCost\",\"objectID\":\"1.3.6.1.2.1.17.2.6\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The port number of the port that offers the lowest\\ncost path from this bridge to the root bridge.\",\"index\":[],\"name\":\"dot1dStpRootPort\",\"objectID\":\"1.3.6.1.2.1.17.2.7\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The maximum age of Spanning Tree Protocol information\\nlearned from the network on any port before it is\\ndiscarded, in units of hundredths of a second.  This is\\nthe actual value that this bridge is currently using.\",\"index\":[],\"name\":\"dot1dStpMaxAge\",\"objectID\":\"1.3.6.1.2.1.17.2.8\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The amount of time between the transmission of\\nConfiguration bridge PDUs by this node on any port when\\nit is the root of the spanning tree, or trying to become\\nso, in units of hundredths of a second.  This is the\\nactual value that this bridge is currently using.\",\"index\":[],\"name\":\"dot1dStpHelloTime\",\"objectID\":\"1.3.6.1.2.1.17.2.9\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This time value determines the interval length\\nduring which no more than two Configuration bridge\\nPDUs shall be transmitted by this node, in units\\nof hundredths of a second.\",\"index\":[],\"name\":\"dot1dStpHoldTime\",\"objectID\":\"1.3.6.1.2.1.17.2.10\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This time value, measured in units of hundredths of a\\nsecond, controls how fast a port changes its spanning\\nstate when moving towards the Forwarding state.  The\\nvalue determines how long the port stays in each of the\\nListening and Learning states, which precede the\\nForwarding state.  This value is also used when a\\ntopology change has been detected and is underway, to\\nage all dynamic entries in the Forwarding Database.\\n[Note that this value is the one that this bridge is\\ncurrently using, in contrast to\\ndot1dStpBridgeForwardDelay, which is the value that this\\nbridge and all others would start using if/when this\\nbridge were to become the root.]\",\"index\":[],\"name\":\"dot1dStpForwardDelay\",\"objectID\":\"1.3.6.1.2.1.17.2.11\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The value that all bridges use for MaxAge when this\\nbridge is acting as the root.  Note that 802.1D-1998\\nspecifies that the range for this parameter is related\\nto the value of dot1dStpBridgeHelloTime.  The\\ngranularity of this timer is specified by 802.1D-1998 to\\nbe 1 second.  An agent may return a badValue error if a\\nset is attempted to a value that is not a whole number\\nof seconds.\",\"index\":[],\"name\":\"dot1dStpBridgeMaxAge\",\"objectID\":\"1.3.6.1.2.1.17.2.12\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The value that all bridges use for HelloTime when this\\nbridge is acting as the root.  The granularity of this\\ntimer is specified by 802.1D-1998 to be 1 second.  An\\nagent may return a badValue error if a set is attempted\\n\\nto a value that is not a whole number of seconds.\",\"index\":[],\"name\":\"dot1dStpBridgeHelloTime\",\"objectID\":\"1.3.6.1.2.1.17.2.13\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The value that all bridges use for ForwardDelay when\\nthis bridge is acting as the root.  Note that\\n802.1D-1998 specifies that the range for this parameter\\nis related to the value of dot1dStpBridgeMaxAge.  The\\ngranularity of this timer is specified by 802.1D-1998 to\\nbe 1 second.  An agent may return a badValue error if a\\nset is attempted to a value that is not a whole number\\nof seconds.\",\"index\":[],\"name\":\"dot1dStpBridgeForwardDelay\",\"objectID\":\"1.3.6.1.2.1.17.2.14\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A table that contains port-specific information\\nfor the Spanning Tree Protocol.\",\"index\":[],\"name\":\"dot1dStpPortTable\",\"objectID\":\"1.3.6.1.2.1.17.2.15\",\"pid\":\"1.3.6.1.2.1.17.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A list of information maintained by every port about\\nthe Spanning Tree Protocol state for that port.\",\"index\":[\"1.3.6.1.2.1.17.2.15.1.1\"],\"name\":\"dot1dStpPortEntry\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1\",\"pid\":\"1.3.6.1.2.1.17.2.15\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The port number of the port for which this entry\\ncontains Spanning Tree Protocol management information.\",\"index\":[],\"name\":\"dot1dStpPort\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.1\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The value of the priority field that is contained in\\nthe first (in network byte order) octet of the (2 octet\\nlong) Port ID.  The other octet of the Port ID is given\\nby the value of dot1dStpPort.\\nOn bridges supporting IEEE 802.1t or IEEE 802.1w,\\npermissible values are 0-240, in steps of 16.\",\"index\":[],\"name\":\"dot1dStpPortPriority\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.2\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The port\'s current state, as defined by application of\\nthe Spanning Tree Protocol.  This state controls what\\naction a port takes on reception of a frame.  If the\\nbridge has detected a port that is malfunctioning, it\\nwill place that port into the broken(6) state.  For\\nports that are disabled (see dot1dStpPortEnable), this\\nobject will have a value of disabled(1).\",\"index\":[],\"name\":\"dot1dStpPortState\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.3\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The enabled/disabled status of the port.\",\"index\":[],\"name\":\"dot1dStpPortEnable\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.4\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The contribution of this port to the path cost of\\npaths towards the spanning tree root which include\\nthis port.  802.1D-1998 recommends that the default\\nvalue of this parameter be in inverse proportion to\\n\\nthe speed of the attached LAN.\\n\\nNew implementations should support dot1dStpPortPathCost32.\\nIf the port path costs exceeds the maximum value of this\\nobject then this object should report the maximum value,\\nnamely 65535.  Applications should try to read the\\ndot1dStpPortPathCost32 object if this object reports\\nthe maximum value.\",\"index\":[],\"name\":\"dot1dStpPortPathCost\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.5\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The unique Bridge Identifier of the Bridge\\nrecorded as the Root in the Configuration BPDUs\\ntransmitted by the Designated Bridge for the\\nsegment to which the port is attached.\",\"index\":[],\"name\":\"dot1dStpPortDesignatedRoot\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.6\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The path cost of the Designated Port of the segment\\nconnected to this port.  This value is compared to the\\nRoot Path Cost field in received bridge PDUs.\",\"index\":[],\"name\":\"dot1dStpPortDesignatedCost\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.7\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The Bridge Identifier of the bridge that this\\nport considers to be the Designated Bridge for\\nthis port\'s segment.\",\"index\":[],\"name\":\"dot1dStpPortDesignatedBridge\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.8\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The Port Identifier of the port on the Designated\\nBridge for this port\'s segment.\",\"index\":[],\"name\":\"dot1dStpPortDesignatedPort\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.9\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of times this port has transitioned\\nfrom the Learning state to the Forwarding state.\",\"index\":[],\"name\":\"dot1dStpPortForwardTransitions\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.10\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The contribution of this port to the path cost of\\npaths towards the spanning tree root which include\\nthis port.  802.1D-1998 recommends that the default\\nvalue of this parameter be in inverse proportion to\\nthe speed of the attached LAN.\\n\\nThis object replaces dot1dStpPortPathCost to support\\nIEEE 802.1t.\",\"index\":[],\"name\":\"dot1dStpPortPathCost32\",\"objectID\":\"1.3.6.1.2.1.17.2.15.1.11\",\"pid\":\"1.3.6.1.2.1.17.2.15.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"dot1dSr\",\"objectID\":\"1.3.6.1.2.1.17.3\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"dot1dTp\",\"objectID\":\"1.3.6.1.2.1.17.4\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The total number of Forwarding Database entries that\\nhave been or would have been learned, but have been\\ndiscarded due to a lack of storage space in the\\nForwarding Database.  If this counter is increasing, it\\nindicates that the Forwarding Database is regularly\\nbecoming full (a condition that has unpleasant\\nperformance effects on the subnetwork).  If this counter\\nhas a significant value but is not presently increasing,\\nit indicates that the problem has been occurring but is\\nnot persistent.\",\"index\":[],\"name\":\"dot1dTpLearnedEntryDiscards\",\"objectID\":\"1.3.6.1.2.1.17.4.1\",\"pid\":\"1.3.6.1.2.1.17.4\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The timeout period in seconds for aging out\\ndynamically-learned forwarding information.\\n802.1D-1998 recommends a default of 300 seconds.\",\"index\":[],\"name\":\"dot1dTpAgingTime\",\"objectID\":\"1.3.6.1.2.1.17.4.2\",\"pid\":\"1.3.6.1.2.1.17.4\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A table that contains information about unicast\\nentries for which the bridge has forwarding and/or\\nfiltering information.  This information is used\\nby the transparent bridging function in\\ndetermining how to propagate a received frame.\",\"index\":[],\"name\":\"dot1dTpFdbTable\",\"objectID\":\"1.3.6.1.2.1.17.4.3\",\"pid\":\"1.3.6.1.2.1.17.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information about a specific unicast MAC address\\nfor which the bridge has some forwarding and/or\\nfiltering information.\",\"index\":[\"1.3.6.1.2.1.17.4.3.1.1\"],\"name\":\"dot1dTpFdbEntry\",\"objectID\":\"1.3.6.1.2.1.17.4.3.1\",\"pid\":\"1.3.6.1.2.1.17.4.3\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"A unicast MAC address for which the bridge has\\nforwarding and/or filtering information.\",\"index\":[],\"name\":\"dot1dTpFdbAddress\",\"objectID\":\"1.3.6.1.2.1.17.4.3.1.1\",\"pid\":\"1.3.6.1.2.1.17.4.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Either the value \'0\', or the port number of the port on\\nwhich a frame having a source address equal to the value\\nof the corresponding instance of dot1dTpFdbAddress has\\nbeen seen.  A value of \'0\' indicates that the port\\nnumber has not been learned, but that the bridge does\\nhave some forwarding/filtering information about this\\naddress (e.g., in the dot1dStaticTable).  Implementors\\nare encouraged to assign the port value to this object\\nwhenever it is learned, even for addresses for which the\\ncorresponding value of dot1dTpFdbStatus is not\\nlearned(3).\",\"index\":[],\"name\":\"dot1dTpFdbPort\",\"objectID\":\"1.3.6.1.2.1.17.4.3.1.2\",\"pid\":\"1.3.6.1.2.1.17.4.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The status of this entry.  The meanings of the\\nvalues are:\\n    other(1) - none of the following.  This would\\n        include the case where some other MIB object\\n        (not the corresponding instance of\\n        dot1dTpFdbPort, nor an entry in the\\n        dot1dStaticTable) is being used to determine if\\n        and how frames addressed to the value of the\\n        corresponding instance of dot1dTpFdbAddress are\\n        being forwarded.\\n    invalid(2) - this entry is no longer valid (e.g.,\\n        it was learned but has since aged out), but has\\n        not yet been flushed from the table.\\n    learned(3) - the value of the corresponding instance\\n        of dot1dTpFdbPort was learned, and is being\\n        used.\\n    self(4) - the value of the corresponding instance of\\n        dot1dTpFdbAddress represents one of the bridge\'s\\n        addresses.  The corresponding instance of\\n        dot1dTpFdbPort indicates which of the bridge\'s\\n        ports has this address.\\n    mgmt(5) - the value of the corresponding instance of\\n        dot1dTpFdbAddress is also the value of an\\n        existing instance of dot1dStaticAddress.\",\"index\":[],\"name\":\"dot1dTpFdbStatus\",\"objectID\":\"1.3.6.1.2.1.17.4.3.1.3\",\"pid\":\"1.3.6.1.2.1.17.4.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"A table that contains information about every port that\\nis associated with this transparent bridge.\",\"index\":[],\"name\":\"dot1dTpPortTable\",\"objectID\":\"1.3.6.1.2.1.17.4.4\",\"pid\":\"1.3.6.1.2.1.17.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A list of information for each port of a transparent\\nbridge.\",\"index\":[\"1.3.6.1.2.1.17.4.4.1.1\"],\"name\":\"dot1dTpPortEntry\",\"objectID\":\"1.3.6.1.2.1.17.4.4.1\",\"pid\":\"1.3.6.1.2.1.17.4.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The port number of the port for which this entry\\ncontains Transparent bridging management information.\",\"index\":[],\"name\":\"dot1dTpPort\",\"objectID\":\"1.3.6.1.2.1.17.4.4.1.1\",\"pid\":\"1.3.6.1.2.1.17.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The maximum size of the INFO (non-MAC) field that\\n\\nthis port will receive or transmit.\",\"index\":[],\"name\":\"dot1dTpPortMaxInfo\",\"objectID\":\"1.3.6.1.2.1.17.4.4.1.2\",\"pid\":\"1.3.6.1.2.1.17.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of frames that have been received by this\\nport from its segment.  Note that a frame received on the\\ninterface corresponding to this port is only counted by\\nthis object if and only if it is for a protocol being\\nprocessed by the local bridging function, including\\nbridge management frames.\",\"index\":[],\"name\":\"dot1dTpPortInFrames\",\"objectID\":\"1.3.6.1.2.1.17.4.4.1.3\",\"pid\":\"1.3.6.1.2.1.17.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of frames that have been transmitted by this\\nport to its segment.  Note that a frame transmitted on\\nthe interface corresponding to this port is only counted\\nby this object if and only if it is for a protocol being\\nprocessed by the local bridging function, including\\nbridge management frames.\",\"index\":[],\"name\":\"dot1dTpPortOutFrames\",\"objectID\":\"1.3.6.1.2.1.17.4.4.1.4\",\"pid\":\"1.3.6.1.2.1.17.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"Count of received valid frames that were discarded\\n(i.e., filtered) by the Forwarding Process.\",\"index\":[],\"name\":\"dot1dTpPortInDiscards\",\"objectID\":\"1.3.6.1.2.1.17.4.4.1.5\",\"pid\":\"1.3.6.1.2.1.17.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"dot1dStatic\",\"objectID\":\"1.3.6.1.2.1.17.5\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A table containing filtering information configured\\ninto the bridge by (local or network) management\\nspecifying the set of ports to which frames received\\nfrom specific ports and containing specific destination\\naddresses are allowed to be forwarded.  The value of\\nzero in this table, as the port number from which frames\\nwith a specific destination address are received, is\\nused to specify all ports for which there is no specific\\nentry in this table for that particular destination\\naddress.  Entries are valid for unicast and for\\ngroup/broadcast addresses.\",\"index\":[],\"name\":\"dot1dStaticTable\",\"objectID\":\"1.3.6.1.2.1.17.5.1\",\"pid\":\"1.3.6.1.2.1.17.5\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Filtering information configured into the bridge by\\n(local or network) management specifying the set of\\nports to which frames received from a specific port and\\ncontaining a specific destination address are allowed to\\nbe forwarded.\",\"index\":[\"1.3.6.1.2.1.17.5.1.1.1\",\"1.3.6.1.2.1.17.5.1.1.2\"],\"name\":\"dot1dStaticEntry\",\"objectID\":\"1.3.6.1.2.1.17.5.1.1\",\"pid\":\"1.3.6.1.2.1.17.5.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"The destination MAC address in a frame to which this\\nentry\'s filtering information applies.  This object can\\ntake the value of a unicast address, a group address, or\\nthe broadcast address.\",\"index\":[],\"name\":\"dot1dStaticAddress\",\"objectID\":\"1.3.6.1.2.1.17.5.1.1.1\",\"pid\":\"1.3.6.1.2.1.17.5.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"Either the value \'0\', or the port number of the port\\nfrom which a frame must be received in order for this\\nentry\'s filtering information to apply.  A value of zero\\nindicates that this entry applies on all ports of the\\nbridge for which there is no other applicable entry.\",\"index\":[],\"name\":\"dot1dStaticReceivePort\",\"objectID\":\"1.3.6.1.2.1.17.5.1.1.2\",\"pid\":\"1.3.6.1.2.1.17.5.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The set of ports to which frames received from a\\nspecific port and destined for a specific MAC address,\\nare allowed to be forwarded.  Each octet within the\\nvalue of this object specifies a set of eight ports,\\nwith the first octet specifying ports 1 through 8, the\\nsecond octet specifying ports 9 through 16, etc.  Within\\neach octet, the most significant bit represents the\\nlowest numbered port, and the least significant bit\\nrepresents the highest numbered port.  Thus, each port\\nof the bridge is represented by a single bit within the\\nvalue of this object.  If that bit has a value of \'1\',\\nthen that port is included in the set of ports; the port\\nis not included if its bit has a value of \'0\'.  (Note\\nthat the setting of the bit corresponding to the port\\nfrom which a frame is received is irrelevant.)  The\\ndefault value of this object is a string of ones of\\nappropriate length.\\n\\nThe value of this object may exceed the required minimum\\nmaximum message size of some SNMP transport (484 bytes,\\nin the case of SNMP over UDP, see RFC 3417, section 3.2).\\nSNMP engines on bridges supporting a large number of\\nports must support appropriate maximum message sizes.\",\"index\":[],\"name\":\"dot1dStaticAllowedToGoTo\",\"objectID\":\"1.3.6.1.2.1.17.5.1.1.3\",\"pid\":\"1.3.6.1.2.1.17.5.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dStaticStatus\",\"objectID\":\"1.3.6.1.2.1.17.5.1.1.4\",\"pid\":\"1.3.6.1.2.1.17.5.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"dot1dConformance\",\"objectID\":\"1.3.6.1.2.1.17.8\",\"pid\":\"1.3.6.1.2.1.17\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dGroups\",\"objectID\":\"1.3.6.1.2.1.17.8.1\",\"pid\":\"1.3.6.1.2.1.17.8\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dBaseBridgeGroup\",\"objectID\":\"1.3.6.1.2.1.17.8.1.1\",\"pid\":\"1.3.6.1.2.1.17.8.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dBasePortGroup\",\"objectID\":\"1.3.6.1.2.1.17.8.1.2\",\"pid\":\"1.3.6.1.2.1.17.8.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dStpBridgeGroup\",\"objectID\":\"1.3.6.1.2.1.17.8.1.3\",\"pid\":\"1.3.6.1.2.1.17.8.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dStpPortGroup\",\"objectID\":\"1.3.6.1.2.1.17.8.1.4\",\"pid\":\"1.3.6.1.2.1.17.8.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dStpPortGroup2\",\"objectID\":\"1.3.6.1.2.1.17.8.1.5\",\"pid\":\"1.3.6.1.2.1.17.8.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dStpPortGroup3\",\"objectID\":\"1.3.6.1.2.1.17.8.1.6\",\"pid\":\"1.3.6.1.2.1.17.8.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dTpBridgeGroup\",\"objectID\":\"1.3.6.1.2.1.17.8.1.7\",\"pid\":\"1.3.6.1.2.1.17.8.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dTpFdbGroup\",\"objectID\":\"1.3.6.1.2.1.17.8.1.8\",\"pid\":\"1.3.6.1.2.1.17.8.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dTpGroup\",\"objectID\":\"1.3.6.1.2.1.17.8.1.9\",\"pid\":\"1.3.6.1.2.1.17.8.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dStaticGroup\",\"objectID\":\"1.3.6.1.2.1.17.8.1.10\",\"pid\":\"1.3.6.1.2.1.17.8.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dNotificationGroup\",\"objectID\":\"1.3.6.1.2.1.17.8.1.11\",\"pid\":\"1.3.6.1.2.1.17.8.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"dot1dCompliances\",\"objectID\":\"1.3.6.1.2.1.17.8.2\",\"pid\":\"1.3.6.1.2.1.17.8\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"bridgeCompliance1493\",\"objectID\":\"1.3.6.1.2.1.17.8.2.1\",\"pid\":\"1.3.6.1.2.1.17.8.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object indicates the status of this entry.\\nThe default value is permanent(3).\\n    other(1) - this entry is currently in use but the\\n        conditions under which it will remain so are\\n        different from each of the following values.\\n    invalid(2) - writing this value to the object\\n        removes the corresponding entry.\\n    permanent(3) - this entry is currently in use and\\n        will remain so after the next reset of the\\n        bridge.\\n    deleteOnReset(4) - this entry is currently in use\\n        and will remain so until the next reset of the\\n        bridge.\\n    deleteOnTimeout(5) - this entry is currently in use\\n        and will remain so until it is aged out.\",\"index\":[],\"name\":\"bridgeCompliance4188\",\"objectID\":\"1.3.6.1.2.1.17.8.2.2\",\"pid\":\"1.3.6.1.2.1.17.8.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"type\":\"IDENTIFIER\"}],\"type\":\"OBJECT\"}]}');
INSERT INTO `snmp_mib`(`id`, `name`, `file_name`, `content`, `models`, `remark`, `update_by`, `update_at`, `tree`) VALUES (3, 'COROSYNC-MIB', 'COROSYNC-MIB.txt', , '', '', 1, '2021-09-29 11:55:38', '{\"COROSYNC-MIB\":[{\"index\":[],\"name\":\"corosync\",\"objectID\":\"1.3.6.1.4.1.35488\",\"pid\":\"1.3.6.1.4.1\",\"subTree\":[{\"index\":[],\"name\":\"corosyncNotices\",\"objectID\":\"1.3.6.1.4.1.35488.0\",\"pid\":\"1.3.6.1.4.1.35488\",\"subTree\":[{\"access\":\"accessible-for-notify\",\"description\":\"Application status\",\"index\":[],\"name\":\"corosyncNoticesNodeStatus\",\"objectID\":\"1.3.6.1.4.1.35488.0.1\",\"pid\":\"1.3.6.1.4.1.35488.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"Application status\",\"index\":[],\"name\":\"corosyncNoticesQuorumStatus\",\"objectID\":\"1.3.6.1.4.1.35488.0.2\",\"pid\":\"1.3.6.1.4.1.35488.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"Application status\",\"index\":[],\"name\":\"corosyncNoticesAppStatus\",\"objectID\":\"1.3.6.1.4.1.35488.0.3\",\"pid\":\"1.3.6.1.4.1.35488.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"Application status\",\"index\":[],\"name\":\"corosyncNoticesRRPStatus\",\"objectID\":\"1.3.6.1.4.1.35488.0.4\",\"pid\":\"1.3.6.1.4.1.35488.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"corosyncObjects\",\"objectID\":\"1.3.6.1.4.1.35488.1\",\"pid\":\"1.3.6.1.4.1.35488\",\"subTree\":[{\"access\":\"accessible-for-notify\",\"description\":\"Hostname of the cluster node.\",\"index\":[],\"name\":\"corosyncObjectsNodeName\",\"objectID\":\"1.3.6.1.4.1.35488.1.1\",\"pid\":\"1.3.6.1.4.1.35488.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The unique integer of the node.\",\"index\":[],\"name\":\"corosyncObjectsNodeID\",\"objectID\":\"1.3.6.1.4.1.35488.1.2\",\"pid\":\"1.3.6.1.4.1.35488.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The status of the node.\",\"index\":[],\"name\":\"corosyncObjectsNodeStatus\",\"objectID\":\"1.3.6.1.4.1.35488.1.3\",\"pid\":\"1.3.6.1.4.1.35488.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The address of the node.\",\"index\":[],\"name\":\"corosyncObjectsNodeAddress\",\"objectID\":\"1.3.6.1.4.1.35488.1.4\",\"pid\":\"1.3.6.1.4.1.35488.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"Ring ID Sequence number\",\"index\":[],\"name\":\"corosyncObjectsRingSeq\",\"objectID\":\"1.3.6.1.4.1.35488.1.20\",\"pid\":\"1.3.6.1.4.1.35488.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"Quorum Status\",\"index\":[],\"name\":\"corosyncObjectsQuorumStatus\",\"objectID\":\"1.3.6.1.4.1.35488.1.21\",\"pid\":\"1.3.6.1.4.1.35488.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The integer of interface.\",\"index\":[],\"name\":\"corosyncObjectsIfaceNo\",\"objectID\":\"1.3.6.1.4.1.35488.1.60\",\"pid\":\"1.3.6.1.4.1.35488.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"RRP Status\",\"index\":[],\"name\":\"corosyncObjectsRRPStatus\",\"objectID\":\"1.3.6.1.4.1.35488.1.61\",\"pid\":\"1.3.6.1.4.1.35488.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"Application name\",\"index\":[],\"name\":\"corosyncObjectsAppName\",\"objectID\":\"1.3.6.1.4.1.35488.1.40\",\"pid\":\"1.3.6.1.4.1.35488.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"Application status\",\"index\":[],\"name\":\"corosyncObjectsAppStatus\",\"objectID\":\"1.3.6.1.4.1.35488.1.41\",\"pid\":\"1.3.6.1.4.1.35488.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"corosyncConformance\",\"objectID\":\"1.3.6.1.4.1.35488.200\",\"pid\":\"1.3.6.1.4.1.35488\",\"subTree\":[{\"access\":\"accessible-for-notify\",\"description\":\"Application status\",\"index\":[],\"name\":\"corosyncCompliances\",\"objectID\":\"1.3.6.1.4.1.35488.200.1\",\"pid\":\"1.3.6.1.4.1.35488.200\",\"status\":\"current\",\"subTree\":[{\"access\":\"accessible-for-notify\",\"description\":\"Application status\",\"index\":[],\"name\":\"corosyncCompliance\",\"objectID\":\"1.3.6.1.4.1.35488.200.1.1\",\"pid\":\"1.3.6.1.4.1.35488.200.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"}],\"syntax\":\"OCTET STRING\",\"type\":\"IDENTIFIER\"},{\"access\":\"accessible-for-notify\",\"description\":\"Application status\",\"index\":[],\"name\":\"corosyncConformanceGroups\",\"objectID\":\"1.3.6.1.4.1.35488.200.2\",\"pid\":\"1.3.6.1.4.1.35488.200\",\"status\":\"current\",\"subTree\":[{\"access\":\"accessible-for-notify\",\"description\":\"Application status\",\"index\":[],\"name\":\"corosyncObjectGroup\",\"objectID\":\"1.3.6.1.4.1.35488.200.2.1\",\"pid\":\"1.3.6.1.4.1.35488.200.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"Application status\",\"index\":[],\"name\":\"corosyncNotificationGroup\",\"objectID\":\"1.3.6.1.4.1.35488.200.2.2\",\"pid\":\"1.3.6.1.4.1.35488.200.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"}],\"syntax\":\"OCTET STRING\",\"type\":\"IDENTIFIER\"}],\"type\":\"IDENTIFIER\"}],\"type\":\"OBJECT\"}]}');
INSERT INTO `snmp_mib`(`id`, `name`, `file_name`, `content`, `models`, `remark`, `update_by`, `update_at`, `tree`) VALUES (4, 'DISMAN-EVENT-MIB', 'DISMAN-EVENT-MIB.txt', , '', '', 1, '2021-09-29 11:55:45', '{\"DISMAN-EVENT-MIB\":[{\"index\":[],\"name\":\"dismanEventMIB\",\"objectID\":\"1.3.6.1.2.1.88\",\"pid\":\"1.3.6.1.2.1\",\"subTree\":[{\"index\":[],\"name\":\"dismanEventMIBObjects\",\"objectID\":\"1.3.6.1.2.1.88.1\",\"pid\":\"1.3.6.1.2.1.88\",\"subTree\":[{\"index\":[],\"name\":\"mteResource\",\"objectID\":\"1.3.6.1.2.1.88.1.1\",\"pid\":\"1.3.6.1.2.1.88.1\",\"subTree\":[{\"access\":\"read-write\",\"description\":\"The minimum mteTriggerFrequency this system will\\naccept.  A system may use the larger values of this minimum to\\nlessen the impact of constant sampling.  For larger\\nsampling intervals the system samples less often and\\nsuffers less overhead.  This object provides a way to enforce\\nsuch lower overhead for all triggers created after it is\\nset.\\n\\nUnless explicitly resource limited, a system\'s value for\\nthis object SHOULD be 1, allowing as small as a 1 second\\ninterval for ongoing trigger sampling.\\n\\nChanging this value will not invalidate an existing setting\\nof mteTriggerFrequency.\",\"index\":[],\"name\":\"mteResourceSampleMinimum\",\"objectID\":\"1.3.6.1.2.1.88.1.1.1\",\"pid\":\"1.3.6.1.2.1.88.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The maximum number of instance entries this system will\\nsupport for sampling.\\n\\nThese are the entries that maintain state, one for each\\ninstance of each sampled object as selected by\\nmteTriggerValueID.  Note that wildcarded objects result\\nin multiple instances of this state.\\n\\nA value of 0 indicates no preset limit, that is, the limit\\nis dynamic based on system operation and resources.\\n\\nUnless explicitly resource limited, a system\'s value for\\nthis object SHOULD be 0.\\n\\nChanging this value will not eliminate or inhibit existing\\nsample state but could prevent allocation of additional state\\ninformation.\",\"index\":[],\"name\":\"mteResourceSampleInstanceMaximum\",\"objectID\":\"1.3.6.1.2.1.88.1.1.2\",\"pid\":\"1.3.6.1.2.1.88.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of currently active instance entries as\\ndefined for mteResourceSampleInstanceMaximum.\",\"index\":[],\"name\":\"mteResourceSampleInstances\",\"objectID\":\"1.3.6.1.2.1.88.1.1.3\",\"pid\":\"1.3.6.1.2.1.88.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The highest value of mteResourceSampleInstances that has\\noccurred since initialization of the management system.\",\"index\":[],\"name\":\"mteResourceSampleInstancesHigh\",\"objectID\":\"1.3.6.1.2.1.88.1.1.4\",\"pid\":\"1.3.6.1.2.1.88.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The number of times this system could not take a new sample\\nbecause that allocation would have exceeded the limit set by\\nmteResourceSampleInstanceMaximum.\",\"index\":[],\"name\":\"mteResourceSampleInstanceLacks\",\"objectID\":\"1.3.6.1.2.1.88.1.1.5\",\"pid\":\"1.3.6.1.2.1.88.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"mteTrigger\",\"objectID\":\"1.3.6.1.2.1.88.1.2\",\"pid\":\"1.3.6.1.2.1.88.1\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The number of times an attempt to check for a trigger\\ncondition has failed.  This counts individually for each\\nattempt in a group of targets or each attempt for a\\n\\nwildcarded object.\",\"index\":[],\"name\":\"mteTriggerFailures\",\"objectID\":\"1.3.6.1.2.1.88.1.2.1\",\"pid\":\"1.3.6.1.2.1.88.1.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A table of management event trigger information.\",\"index\":[],\"name\":\"mteTriggerTable\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2\",\"pid\":\"1.3.6.1.2.1.88.1.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information about a single trigger.  Applications create and\\ndelete entries using mteTriggerEntryStatus.\",\"index\":[\"1.3.6.1.2.1.88.1.2.2.1.1\",\"IMPLIED 1.3.6.1.2.1.88.1.2.2.1.2\"],\"name\":\"mteTriggerEntry\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1\",\"pid\":\"1.3.6.1.2.1.88.1.2.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"The owner of this entry. The exact semantics of this\\nstring are subject to the security policy defined by the\\nsecurity administrator.\",\"index\":[],\"name\":\"mteOwner\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.1\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A locally-unique, administratively assigned name for the\\ntrigger within the scope of mteOwner.\",\"index\":[],\"name\":\"mteTriggerName\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.2\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"A description of the trigger\'s function and use.\",\"index\":[],\"name\":\"mteTriggerComment\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.3\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The type of trigger test to perform.  For \'boolean\' and\\n\'threshold\'  tests, the object at mteTriggerValueID MUST\\nevaluate to an integer, that is, anything that ends up encoded\\nfor transmission (that is, in BER, not ASN.1) as an integer.\\n\\nFor \'existence\', the specific test is as selected by\\nmteTriggerExistenceTest.  When an object appears, vanishes\\nor changes value, the trigger fires. If the object\'s\\nappearance caused the trigger firing, the object MUST\\nvanish before the trigger can be fired again for it, and\\nvice versa. If the trigger fired due to a change in the\\nobject\'s value, it will be fired again on every successive\\nvalue change for that object.\\n\\nFor \'boolean\', the specific test is as selected by\\nmteTriggerBooleanTest.  If the test result is true the trigger\\nfires.  The trigger will not fire again until the value has\\nbecome false and come back to true.\\n\\nFor \'threshold\' the test works as described below for\\n\\nmteTriggerThresholdStartup, mteTriggerThresholdRising, and\\nmteTriggerThresholdFalling.\\n\\nNote that combining \'boolean\' and \'threshold\' tests on the\\nsame object may be somewhat redundant.\",\"index\":[],\"name\":\"mteTriggerTest\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.4\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"BITS\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The type of sampling to perform.\\n\\nAn \'absoluteValue\' sample requires only a single sample to be\\nmeaningful, and is exactly the value of the object at\\nmteTriggerValueID at the sample time.\\n\\nA \'deltaValue\' requires two samples to be meaningful and is\\nthus not available for testing until the second and subsequent\\nsamples after the object at mteTriggerValueID is first found\\nto exist.  It is the difference between the two samples.  For\\nunsigned values it is always positive, based on unsigned\\narithmetic.  For signed values it can be positive or negative.\\n\\nFor SNMP counters to be meaningful they should be sampled as a\\n\'deltaValue\'.\\n\\nFor \'deltaValue\' mteTriggerDeltaTable contains further\\nparameters.\\n\\nIf only \'existence\' is set in mteTriggerTest this object has\\nno meaning.\",\"index\":[],\"name\":\"mteTriggerSampleType\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.5\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The object identifier of the MIB object to sample to see\\nif the trigger should fire.\\n\\nThis may be wildcarded by truncating all or part of the\\ninstance portion, in which case the value is obtained\\nas if with a GetNext function, checking multiple values\\n\\nif they exist.  If such wildcarding is applied,\\nmteTriggerValueIDWildcard must be \'true\' and if not it must\\nbe \'false\'.\\n\\nBad object identifiers or a mismatch between truncating the\\nidentifier and the value of mteTriggerValueIDWildcard result\\nin operation as one would expect when providing the wrong\\nidentifier to a Get or GetNext operation.  The Get will fail\\nor get the wrong object.  The GetNext will indeed get whatever\\nis next, proceeding until it runs past the initial part of the\\nidentifier and perhaps many unintended objects for confusing\\nresults.  If the value syntax of those objects is not usable,\\nthat results in a \'badType\' error that terminates the scan.\\n\\nEach instance that fills the wildcard is independent of any\\nadditional instances, that is, wildcarded objects operate\\nas if there were a separate table entry for each instance\\nthat fills the wildcard without having to actually predict\\nall possible instances ahead of time.\",\"index\":[],\"name\":\"mteTriggerValueID\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.6\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"Control for whether mteTriggerValueID is to be treated as\\nfully-specified or wildcarded, with \'true\' indicating wildcard.\",\"index\":[],\"name\":\"mteTriggerValueIDWildcard\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.7\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The tag for the target(s) from which to obtain the condition\\nfor a trigger check.\\n\\nA length of 0 indicates the local system.  In this case,\\naccess to the objects indicated by mteTriggerValueID is under\\nthe security credentials of the requester that set\\nmteTriggerEntryStatus to \'active\'.  Those credentials are the\\ninput parameters for isAccessAllowed from the Architecture for\\nDescribing SNMP Management Frameworks.\\n\\nOtherwise access rights are checked according to the security\\n\\nparameters resulting from the tag.\",\"index\":[],\"name\":\"mteTriggerTargetTag\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.8\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The management context from which to obtain mteTriggerValueID.\\n\\nThis may be wildcarded by leaving characters off the end.  For\\nexample use \'Repeater\' to wildcard to \'Repeater1\',\\n\'Repeater2\', \'Repeater-999.87b\', and so on.  To indicate such\\nwildcarding is intended, mteTriggerContextNameWildcard must\\nbe \'true\'.\\n\\nEach instance that fills the wildcard is independent of any\\nadditional instances, that is, wildcarded objects operate\\nas if there were a separate table entry for each instance\\nthat fills the wildcard without having to actually predict\\nall possible instances ahead of time.\\n\\nOperation of this feature assumes that the local system has a\\nlist of available contexts against which to apply the\\nwildcard.  If the objects are being read from the local\\nsystem, this is clearly the system\'s own list of contexts.\\nFor a remote system a local version of such a list is not\\ndefined by any current standard and may not be available, so\\nthis function MAY not be supported.\",\"index\":[],\"name\":\"mteTriggerContextName\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.9\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"Control for whether mteTriggerContextName is to be treated as\\nfully-specified or wildcarded, with \'true\' indicating wildcard.\",\"index\":[],\"name\":\"mteTriggerContextNameWildcard\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.10\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The number of seconds to wait between trigger samples.  To\\nencourage consistency in sampling, the interval is measured\\nfrom the beginning of one check to the beginning of the next\\nand the timer is restarted immediately when it expires, not\\nwhen the check completes.\\n\\nIf the next sample begins before the previous one completed the\\nsystem may either attempt to make the check or treat this as an\\nerror condition with the error \'sampleOverrun\'.\\n\\nA frequency of 0 indicates instantaneous recognition of the\\ncondition.  This is not possible in many cases, but may\\nbe supported in cases where it makes sense and the system is\\nable to do so.  This feature allows the MIB to be used in\\nimplementations where such interrupt-driven behavior is\\npossible and is not likely to be supported for all MIB objects\\neven then since such sampling generally has to be tightly\\nintegrated into low-level code.\\n\\nSystems that can support this SHOULD document those cases\\nwhere it can be used.  In cases where it can not, setting this\\nobject to 0 should be disallowed.\",\"index\":[],\"name\":\"mteTriggerFrequency\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.11\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"To go with mteTriggerObjects, the mteOwner of a group of\\nobjects from mteObjectsTable.\",\"index\":[],\"name\":\"mteTriggerObjectsOwner\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.12\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The mteObjectsName of a group of objects from\\nmteObjectsTable.  These objects are to be added to any\\nNotification resulting from the firing of this trigger.\\n\\nA list of objects may also be added based on the event or on\\nthe value of mteTriggerTest.\\n\\nA length of 0 indicates no additional objects.\",\"index\":[],\"name\":\"mteTriggerObjects\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.13\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"A control to allow a trigger to be configured but not used.\\nWhen the value is \'false\' the trigger is not sampled.\",\"index\":[],\"name\":\"mteTriggerEnabled\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.14\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The control that allows creation and deletion of entries.\\nOnce made active an entry may not be modified except to\\ndelete it.\",\"index\":[],\"name\":\"mteTriggerEntryStatus\",\"objectID\":\"1.3.6.1.2.1.88.1.2.2.1.15\",\"pid\":\"1.3.6.1.2.1.88.1.2.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"A table of management event trigger information for delta\\nsampling.\",\"index\":[],\"name\":\"mteTriggerDeltaTable\",\"objectID\":\"1.3.6.1.2.1.88.1.2.3\",\"pid\":\"1.3.6.1.2.1.88.1.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information about a single trigger\'s delta sampling.  Entries\\nautomatically exist in this this table for each mteTriggerEntry\\nthat has mteTriggerSampleType set to \'deltaValue\'.\",\"index\":[\"1.3.6.1.2.1.88.1.2.2.1.1\",\"IMPLIED 1.3.6.1.2.1.88.1.2.2.1.2\"],\"name\":\"mteTriggerDeltaEntry\",\"objectID\":\"1.3.6.1.2.1.88.1.2.3.1\",\"pid\":\"1.3.6.1.2.1.88.1.2.3\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-write\",\"description\":\"The OBJECT IDENTIFIER (OID) of a TimeTicks, TimeStamp, or\\nDateAndTime object that indicates a discontinuity in the value\\nat mteTriggerValueID.\\n\\nThe OID may be for a leaf object (e.g. sysUpTime.0) or may\\nbe wildcarded to match mteTriggerValueID.\\n\\nThis object supports normal checking for a discontinuity in a\\ncounter.  Note that if this object does not point to sysUpTime\\ndiscontinuity checking MUST still check sysUpTime for an overall\\ndiscontinuity.\\n\\nIf the object identified is not accessible the sample attempt\\nis in error, with the error code as from an SNMP request.\\n\\nBad object identifiers or a mismatch between truncating the\\nidentifier and the value of mteDeltaDiscontinuityIDWildcard\\nresult in operation as one would expect when providing the\\nwrong identifier to a Get operation.  The Get will fail or get\\nthe wrong object.  If the value syntax of those objects is not\\nusable, that results in an error that terminates the sample\\nwith a \'badType\' error code.\",\"index\":[],\"name\":\"mteTriggerDeltaDiscontinuityID\",\"objectID\":\"1.3.6.1.2.1.88.1.2.3.1.1\",\"pid\":\"1.3.6.1.2.1.88.1.2.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"Control for whether mteTriggerDeltaDiscontinuityID is to be\\ntreated as fully-specified or wildcarded, with \'true\'\\nindicating wildcard. Note that the value of this object will\\nbe the same as that of the corresponding instance of\\nmteTriggerValueIDWildcard when the corresponding\\n\\nmteTriggerSampleType is \'deltaValue\'.\",\"index\":[],\"name\":\"mteTriggerDeltaDiscontinuityIDWildcard\",\"objectID\":\"1.3.6.1.2.1.88.1.2.3.1.2\",\"pid\":\"1.3.6.1.2.1.88.1.2.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The value \'timeTicks\' indicates the\\nmteTriggerDeltaDiscontinuityID of this row is of syntax\\nTimeTicks.  The value \'timeStamp\' indicates syntax TimeStamp.\\nThe value \'dateAndTime\' indicates syntax DateAndTime.\",\"index\":[],\"name\":\"mteTriggerDeltaDiscontinuityIDType\",\"objectID\":\"1.3.6.1.2.1.88.1.2.3.1.3\",\"pid\":\"1.3.6.1.2.1.88.1.2.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"A table of management event trigger information for existence\\ntriggers.\",\"index\":[],\"name\":\"mteTriggerExistenceTable\",\"objectID\":\"1.3.6.1.2.1.88.1.2.4\",\"pid\":\"1.3.6.1.2.1.88.1.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information about a single existence trigger.  Entries\\nautomatically exist in this this table for each mteTriggerEntry\\nthat has \'existence\' set in mteTriggerTest.\",\"index\":[\"1.3.6.1.2.1.88.1.2.2.1.1\",\"IMPLIED 1.3.6.1.2.1.88.1.2.2.1.2\"],\"name\":\"mteTriggerExistenceEntry\",\"objectID\":\"1.3.6.1.2.1.88.1.2.4.1\",\"pid\":\"1.3.6.1.2.1.88.1.2.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-write\",\"description\":\"The type of existence test to perform.  The trigger fires\\nwhen the object at mteTriggerValueID is seen to go from\\npresent to absent, from absent to present, or to have it\'s\\nvalue changed, depending on which tests are selected:\\n\\npresent(0) - when this test is selected, the trigger fires\\nwhen the mteTriggerValueID object goes from absent to present.\\n\\nabsent(1)  - when this test is selected, the trigger fires\\nwhen the mteTriggerValueID object goes from present to absent.\\nchanged(2) - when this test is selected, the trigger fires\\nthe mteTriggerValueID object value changes.\\n\\nOnce the trigger has fired for either presence or absence it\\nwill not fire again for that state until the object has been\\nto the other state. \",\"index\":[],\"name\":\"mteTriggerExistenceTest\",\"objectID\":\"1.3.6.1.2.1.88.1.2.4.1.1\",\"pid\":\"1.3.6.1.2.1.88.1.2.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"BITS\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"Control for whether an event may be triggered when this entry\\nis first set to \'active\' and the test specified by\\nmteTriggerExistenceTest is true.  Setting an option causes\\nthat trigger to fire when its test is true.\",\"index\":[],\"name\":\"mteTriggerExistenceStartup\",\"objectID\":\"1.3.6.1.2.1.88.1.2.4.1.2\",\"pid\":\"1.3.6.1.2.1.88.1.2.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"BITS\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"To go with mteTriggerExistenceObjects, the mteOwner of a\\ngroup of objects from mteObjectsTable.\",\"index\":[],\"name\":\"mteTriggerExistenceObjectsOwner\",\"objectID\":\"1.3.6.1.2.1.88.1.2.4.1.3\",\"pid\":\"1.3.6.1.2.1.88.1.2.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The mteObjectsName of a group of objects from\\nmteObjectsTable.  These objects are to be added to any\\nNotification resulting from the firing of this trigger for\\nthis test.\\n\\nA list of objects may also be added based on the overall\\ntrigger, the event or other settings in mteTriggerTest.\\n\\nA length of 0 indicates no additional objects.\",\"index\":[],\"name\":\"mteTriggerExistenceObjects\",\"objectID\":\"1.3.6.1.2.1.88.1.2.4.1.4\",\"pid\":\"1.3.6.1.2.1.88.1.2.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"To go with mteTriggerExistenceEvent, the mteOwner of an event\\nentry from the mteEventTable.\",\"index\":[],\"name\":\"mteTriggerExistenceEventOwner\",\"objectID\":\"1.3.6.1.2.1.88.1.2.4.1.5\",\"pid\":\"1.3.6.1.2.1.88.1.2.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The mteEventName of the event to invoke when mteTriggerType is\\n\'existence\' and this trigger fires.  A length of 0 indicates no\\nevent.\",\"index\":[],\"name\":\"mteTriggerExistenceEvent\",\"objectID\":\"1.3.6.1.2.1.88.1.2.4.1.6\",\"pid\":\"1.3.6.1.2.1.88.1.2.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"A table of management event trigger information for boolean\\ntriggers.\",\"index\":[],\"name\":\"mteTriggerBooleanTable\",\"objectID\":\"1.3.6.1.2.1.88.1.2.5\",\"pid\":\"1.3.6.1.2.1.88.1.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information about a single boolean trigger.  Entries\\nautomatically exist in this this table for each mteTriggerEntry\\nthat has \'boolean\' set in mteTriggerTest.\",\"index\":[\"1.3.6.1.2.1.88.1.2.2.1.1\",\"IMPLIED 1.3.6.1.2.1.88.1.2.2.1.2\"],\"name\":\"mteTriggerBooleanEntry\",\"objectID\":\"1.3.6.1.2.1.88.1.2.5.1\",\"pid\":\"1.3.6.1.2.1.88.1.2.5\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-write\",\"description\":\"The type of boolean comparison to perform.\\n\\nThe value at mteTriggerValueID is compared to\\nmteTriggerBooleanValue, so for example if\\nmteTriggerBooleanComparison is \'less\' the result would be true\\nif the value at mteTriggerValueID is less than the value of\\nmteTriggerBooleanValue.\",\"index\":[],\"name\":\"mteTriggerBooleanComparison\",\"objectID\":\"1.3.6.1.2.1.88.1.2.5.1.1\",\"pid\":\"1.3.6.1.2.1.88.1.2.5.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The value to use for the test specified by\\nmteTriggerBooleanTest.\",\"index\":[],\"name\":\"mteTriggerBooleanValue\",\"objectID\":\"1.3.6.1.2.1.88.1.2.5.1.2\",\"pid\":\"1.3.6.1.2.1.88.1.2.5.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"Control for whether an event may be triggered when this entry\\nis first set to \'active\' or a new instance of the object at\\nmteTriggerValueID is found and the test specified by\\nmteTriggerBooleanComparison is true.  In that case an event is\\ntriggered if mteTriggerBooleanStartup is \'true\'.\",\"index\":[],\"name\":\"mteTriggerBooleanStartup\",\"objectID\":\"1.3.6.1.2.1.88.1.2.5.1.3\",\"pid\":\"1.3.6.1.2.1.88.1.2.5.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"To go with mteTriggerBooleanObjects, the mteOwner of a group\\nof objects from mteObjectsTable.\",\"index\":[],\"name\":\"mteTriggerBooleanObjectsOwner\",\"objectID\":\"1.3.6.1.2.1.88.1.2.5.1.4\",\"pid\":\"1.3.6.1.2.1.88.1.2.5.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The mteObjectsName of a group of objects from\\nmteObjectsTable.  These objects are to be added to any\\nNotification resulting from the firing of this trigger for\\nthis test.\\n\\nA list of objects may also be added based on the overall\\ntrigger, the event or other settings in mteTriggerTest.\\n\\nA length of 0 indicates no additional objects.\",\"index\":[],\"name\":\"mteTriggerBooleanObjects\",\"objectID\":\"1.3.6.1.2.1.88.1.2.5.1.5\",\"pid\":\"1.3.6.1.2.1.88.1.2.5.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"To go with mteTriggerBooleanEvent, the mteOwner of an event\\nentry from mteEventTable.\",\"index\":[],\"name\":\"mteTriggerBooleanEventOwner\",\"objectID\":\"1.3.6.1.2.1.88.1.2.5.1.6\",\"pid\":\"1.3.6.1.2.1.88.1.2.5.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The mteEventName of the event to invoke when mteTriggerType is\\n\'boolean\' and this trigger fires.  A length of 0 indicates no\\nevent.\",\"index\":[],\"name\":\"mteTriggerBooleanEvent\",\"objectID\":\"1.3.6.1.2.1.88.1.2.5.1.7\",\"pid\":\"1.3.6.1.2.1.88.1.2.5.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"A table of management event trigger information for threshold\\ntriggers.\",\"index\":[],\"name\":\"mteTriggerThresholdTable\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6\",\"pid\":\"1.3.6.1.2.1.88.1.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information about a single threshold trigger.  Entries\\nautomatically exist in this table for each mteTriggerEntry\\nthat has \'threshold\' set in mteTriggerTest.\",\"index\":[\"1.3.6.1.2.1.88.1.2.2.1.1\",\"IMPLIED 1.3.6.1.2.1.88.1.2.2.1.2\"],\"name\":\"mteTriggerThresholdEntry\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1\",\"pid\":\"1.3.6.1.2.1.88.1.2.6\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-write\",\"description\":\"The event that may be triggered when this entry is first\\nset to \'active\' and a new instance of the object at\\nmteTriggerValueID is found.  If the first sample after this\\ninstance becomes active is greater than or equal to\\nmteTriggerThresholdRising and mteTriggerThresholdStartup is\\nequal to \'rising\' or \'risingOrFalling\', then one\\nmteTriggerThresholdRisingEvent is triggered for that instance.\\nIf the first sample after this entry becomes active is less\\nthan or equal to mteTriggerThresholdFalling and\\nmteTriggerThresholdStartup is equal to \'falling\' or\\n\'risingOrFalling\', then one mteTriggerThresholdRisingEvent is\\ntriggered for that instance.\",\"index\":[],\"name\":\"mteTriggerThresholdStartup\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.1\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"A threshold value to check against if mteTriggerType is\\n\'threshold\'.\\n\\nWhen the current sampled value is greater than or equal to\\nthis threshold, and the value at the last sampling interval\\nwas less than this threshold, one\\nmteTriggerThresholdRisingEvent is triggered.  That event is\\nalso triggered if the first sample after this entry becomes\\nactive is greater than or equal to this threshold and\\nmteTriggerThresholdStartup is equal to \'rising\' or\\n\'risingOrFalling\'.\\n\\nAfter a rising event is generated, another such event is not\\ntriggered until the sampled value falls below this threshold\\nand reaches mteTriggerThresholdFalling.\",\"index\":[],\"name\":\"mteTriggerThresholdRising\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.2\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"A threshold value to check against if mteTriggerType is\\n\'threshold\'.\\n\\nWhen the current sampled value is less than or equal to this\\nthreshold, and the value at the last sampling interval was\\ngreater than this threshold, one\\nmteTriggerThresholdFallingEvent is triggered.  That event is\\nalso triggered if the first sample after this entry becomes\\nactive is less than or equal to this threshold and\\nmteTriggerThresholdStartup is equal to \'falling\' or\\n\'risingOrFalling\'.\\n\\nAfter a falling event is generated, another such event is not\\ntriggered until the sampled value rises above this threshold\\nand reaches mteTriggerThresholdRising.\",\"index\":[],\"name\":\"mteTriggerThresholdFalling\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.3\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"A threshold value to check against if mteTriggerType is\\n\'threshold\'.\\n\\nWhen the delta value (difference) between the current sampled\\nvalue (value(n)) and the previous sampled value (value(n-1))\\nis greater than or equal to this threshold,\\nand the delta value calculated at the last sampling interval\\n(i.e. value(n-1) - value(n-2)) was less than this threshold,\\none mteTriggerThresholdDeltaRisingEvent is triggered. That event\\nis also triggered if the first delta value calculated after this\\nentry becomes active, i.e. value(2) - value(1), where value(1)\\nis the first sample taken of that instance, is greater than or\\nequal to this threshold.\\n\\nAfter a rising event is generated, another such event is not\\ntriggered until the delta value falls below this threshold and\\nreaches mteTriggerThresholdDeltaFalling.\",\"index\":[],\"name\":\"mteTriggerThresholdDeltaRising\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.4\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"A threshold value to check against if mteTriggerType is\\n\'threshold\'.\\n\\nWhen the delta value (difference) between the current sampled\\nvalue (value(n)) and the previous sampled value (value(n-1))\\nis less than or equal to this threshold,\\nand the delta value calculated at the last sampling interval\\n(i.e. value(n-1) - value(n-2)) was greater than this threshold,\\none mteTriggerThresholdDeltaFallingEvent is triggered. That event\\nis also triggered if the first delta value calculated after this\\nentry becomes active, i.e. value(2) - value(1), where value(1)\\nis the first sample taken of that instance, is less than or\\nequal to this threshold.\\n\\nAfter a falling event is generated, another such event is not\\ntriggered until the delta value falls below this threshold and\\nreaches mteTriggerThresholdDeltaRising.\",\"index\":[],\"name\":\"mteTriggerThresholdDeltaFalling\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.5\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"To go with mteTriggerThresholdObjects, the mteOwner of a group\\nof objects from mteObjectsTable.\",\"index\":[],\"name\":\"mteTriggerThresholdObjectsOwner\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.6\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The mteObjectsName of a group of objects from\\nmteObjectsTable.  These objects are to be added to any\\nNotification resulting from the firing of this trigger for\\nthis test.\\n\\nA list of objects may also be added based on the overall\\n\\ntrigger, the event or other settings in mteTriggerTest.\\n\\nA length of 0 indicates no additional objects.\",\"index\":[],\"name\":\"mteTriggerThresholdObjects\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.7\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"To go with mteTriggerThresholdRisingEvent, the mteOwner of an\\nevent entry from mteEventTable.\",\"index\":[],\"name\":\"mteTriggerThresholdRisingEventOwner\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.8\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The mteEventName of the event to invoke when mteTriggerType is\\n\'threshold\' and this trigger fires based on\\nmteTriggerThresholdRising.  A length of 0 indicates no event.\",\"index\":[],\"name\":\"mteTriggerThresholdRisingEvent\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.9\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"To go with mteTriggerThresholdFallingEvent, the mteOwner of an\\nevent entry from mteEventTable.\",\"index\":[],\"name\":\"mteTriggerThresholdFallingEventOwner\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.10\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The mteEventName of the event to invoke when mteTriggerType is\\n\'threshold\' and this trigger fires based on\\nmteTriggerThresholdFalling.  A length of 0 indicates no event.\",\"index\":[],\"name\":\"mteTriggerThresholdFallingEvent\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.11\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"To go with mteTriggerThresholdDeltaRisingEvent, the mteOwner\\nof an event entry from mteEventTable.\",\"index\":[],\"name\":\"mteTriggerThresholdDeltaRisingEventOwner\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.12\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The mteEventName of the event to invoke when mteTriggerType is\\n\'threshold\' and this trigger fires based on\\nmteTriggerThresholdDeltaRising. A length of 0 indicates\\nno event.\",\"index\":[],\"name\":\"mteTriggerThresholdDeltaRisingEvent\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.13\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"To go with mteTriggerThresholdDeltaFallingEvent, the mteOwner\\nof an event entry from mteEventTable.\",\"index\":[],\"name\":\"mteTriggerThresholdDeltaFallingEventOwner\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.14\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The mteEventName of the event to invoke when mteTriggerType is\\n\'threshold\' and this trigger fires based on\\nmteTriggerThresholdDeltaFalling.  A length of 0 indicates\\nno event.\",\"index\":[],\"name\":\"mteTriggerThresholdDeltaFallingEvent\",\"objectID\":\"1.3.6.1.2.1.88.1.2.6.1.15\",\"pid\":\"1.3.6.1.2.1.88.1.2.6.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"mteObjects\",\"objectID\":\"1.3.6.1.2.1.88.1.3\",\"pid\":\"1.3.6.1.2.1.88.1\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A table of objects that can be added to notifications based\\non the trigger, trigger test, or event, as pointed to by\\nentries in those tables.\",\"index\":[],\"name\":\"mteObjectsTable\",\"objectID\":\"1.3.6.1.2.1.88.1.3.1\",\"pid\":\"1.3.6.1.2.1.88.1.3\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A group of objects.  Applications create and delete entries\\nusing mteObjectsEntryStatus.\\n\\nWhen adding objects to a notification they are added in the\\nlexical order of their index in this table.  Those associated\\nwith a trigger come first, then trigger test, then event.\",\"index\":[\"1.3.6.1.2.1.88.1.2.2.1.1\",\"1.3.6.1.2.1.88.1.3.1.1.1\",\"1.3.6.1.2.1.88.1.3.1.1.2\"],\"name\":\"mteObjectsEntry\",\"objectID\":\"1.3.6.1.2.1.88.1.3.1.1\",\"pid\":\"1.3.6.1.2.1.88.1.3.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A locally-unique, administratively assigned name for a group\\nof objects.\",\"index\":[],\"name\":\"mteObjectsName\",\"objectID\":\"1.3.6.1.2.1.88.1.3.1.1.1\",\"pid\":\"1.3.6.1.2.1.88.1.3.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"An arbitrary integer for the purpose of identifying\\nindividual objects within a mteObjectsName group.\\n\\nObjects within a group are placed in the notification in the\\nnumerical order of this index.\\n\\nGroups are placed in the notification in the order of the\\nselections for overall trigger, trigger test, and event.\\nWithin trigger test they are in the same order as the\\nnumerical values of the bits defined for mteTriggerTest.\\n\\nBad object identifiers or a mismatch between truncating the\\nidentifier and the value of mteDeltaDiscontinuityIDWildcard\\nresult in operation as one would expect when providing the\\nwrong identifier to a Get operation.  The Get will fail or get\\nthe wrong object.  If the object is not available it is omitted\\nfrom the notification.\",\"index\":[],\"name\":\"mteObjectsIndex\",\"objectID\":\"1.3.6.1.2.1.88.1.3.1.1.2\",\"pid\":\"1.3.6.1.2.1.88.1.3.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The object identifier of a MIB object to add to a\\nNotification that results from the firing of a trigger.\\n\\nThis may be wildcarded by truncating all or part of the\\ninstance portion, in which case the instance portion of the\\nOID for obtaining this object will be the same as that used\\nin obtaining the mteTriggerValueID that fired.  If such\\nwildcarding is applied, mteObjectsIDWildcard must be\\n\'true\' and if not it must be \'false\'.\\n\\nEach instance that fills the wildcard is independent of any\\nadditional instances, that is, wildcarded objects operate\\nas if there were a separate table entry for each instance\\nthat fills the wildcard without having to actually predict\\nall possible instances ahead of time.\",\"index\":[],\"name\":\"mteObjectsID\",\"objectID\":\"1.3.6.1.2.1.88.1.3.1.1.3\",\"pid\":\"1.3.6.1.2.1.88.1.3.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"Control for whether mteObjectsID is to be treated as\\nfully-specified or wildcarded, with \'true\' indicating wildcard.\",\"index\":[],\"name\":\"mteObjectsIDWildcard\",\"objectID\":\"1.3.6.1.2.1.88.1.3.1.1.4\",\"pid\":\"1.3.6.1.2.1.88.1.3.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The control that allows creation and deletion of entries.\\nOnce made active an entry MAY not be modified except to\\ndelete it.\",\"index\":[],\"name\":\"mteObjectsEntryStatus\",\"objectID\":\"1.3.6.1.2.1.88.1.3.1.1.5\",\"pid\":\"1.3.6.1.2.1.88.1.3.1.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"mteEvent\",\"objectID\":\"1.3.6.1.2.1.88.1.4\",\"pid\":\"1.3.6.1.2.1.88.1\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The number of times an attempt to invoke an event\\nhas failed.  This counts individually for each\\nattempt in a group of targets or each attempt for a\\nwildcarded trigger object.\",\"index\":[],\"name\":\"mteEventFailures\",\"objectID\":\"1.3.6.1.2.1.88.1.4.1\",\"pid\":\"1.3.6.1.2.1.88.1.4\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"A table of management event action information.\",\"index\":[],\"name\":\"mteEventTable\",\"objectID\":\"1.3.6.1.2.1.88.1.4.2\",\"pid\":\"1.3.6.1.2.1.88.1.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information about a single event.  Applications create and\\ndelete entries using mteEventEntryStatus.\",\"index\":[\"1.3.6.1.2.1.88.1.2.2.1.1\",\"IMPLIED 1.3.6.1.2.1.88.1.4.2.1.1\"],\"name\":\"mteEventEntry\",\"objectID\":\"1.3.6.1.2.1.88.1.4.2.1\",\"pid\":\"1.3.6.1.2.1.88.1.4.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"A locally-unique, administratively assigned name for the\\nevent.\",\"index\":[],\"name\":\"mteEventName\",\"objectID\":\"1.3.6.1.2.1.88.1.4.2.1.1\",\"pid\":\"1.3.6.1.2.1.88.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"A description of the event\'s function and use.\",\"index\":[],\"name\":\"mteEventComment\",\"objectID\":\"1.3.6.1.2.1.88.1.4.2.1.2\",\"pid\":\"1.3.6.1.2.1.88.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The actions to perform when this event occurs.\\n\\nFor \'notification\', Traps and/or Informs are sent according\\nto the configuration in the SNMP Notification MIB.\\n\\nFor \'set\', an SNMP Set operation is performed according to\\ncontrol values in this entry.\",\"index\":[],\"name\":\"mteEventActions\",\"objectID\":\"1.3.6.1.2.1.88.1.4.2.1.3\",\"pid\":\"1.3.6.1.2.1.88.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"BITS\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"A control to allow an event to be configured but not used.\\nWhen the value is \'false\' the event does not execute even if\\n\\ntriggered.\",\"index\":[],\"name\":\"mteEventEnabled\",\"objectID\":\"1.3.6.1.2.1.88.1.4.2.1.4\",\"pid\":\"1.3.6.1.2.1.88.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The control that allows creation and deletion of entries.\\nOnce made active an entry MAY not be modified except to\\ndelete it.\",\"index\":[],\"name\":\"mteEventEntryStatus\",\"objectID\":\"1.3.6.1.2.1.88.1.4.2.1.5\",\"pid\":\"1.3.6.1.2.1.88.1.4.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"A table of information about notifications to be sent as a\\nconsequence of management events.\",\"index\":[],\"name\":\"mteEventNotificationTable\",\"objectID\":\"1.3.6.1.2.1.88.1.4.3\",\"pid\":\"1.3.6.1.2.1.88.1.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information about a single event\'s notification.  Entries\\nautomatically exist in this this table for each mteEventEntry\\nthat has \'notification\' set in mteEventActions.\",\"index\":[\"1.3.6.1.2.1.88.1.2.2.1.1\",\"IMPLIED 1.3.6.1.2.1.88.1.4.2.1.1\"],\"name\":\"mteEventNotificationEntry\",\"objectID\":\"1.3.6.1.2.1.88.1.4.3.1\",\"pid\":\"1.3.6.1.2.1.88.1.4.3\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-write\",\"description\":\"The object identifier from the NOTIFICATION-TYPE for the\\nnotification to use if metEventActions has \'notification\' set.\",\"index\":[],\"name\":\"mteEventNotification\",\"objectID\":\"1.3.6.1.2.1.88.1.4.3.1.1\",\"pid\":\"1.3.6.1.2.1.88.1.4.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"To go with mteEventNotificationObjects, the mteOwner of a\\ngroup of objects from mteObjectsTable.\",\"index\":[],\"name\":\"mteEventNotificationObjectsOwner\",\"objectID\":\"1.3.6.1.2.1.88.1.4.3.1.2\",\"pid\":\"1.3.6.1.2.1.88.1.4.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The mteObjectsName of a group of objects from\\nmteObjectsTable if mteEventActions has \'notification\' set.\\nThese objects are to be added to any Notification generated by\\nthis event.\\n\\nObjects may also be added based on the trigger that stimulated\\nthe event.\\n\\nA length of 0 indicates no additional objects.\",\"index\":[],\"name\":\"mteEventNotificationObjects\",\"objectID\":\"1.3.6.1.2.1.88.1.4.3.1.3\",\"pid\":\"1.3.6.1.2.1.88.1.4.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"},{\"access\":\"not-accessible\",\"description\":\"A table of management event action information.\",\"index\":[],\"name\":\"mteEventSetTable\",\"objectID\":\"1.3.6.1.2.1.88.1.4.4\",\"pid\":\"1.3.6.1.2.1.88.1.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"Information about a single event\'s set option.  Entries\\nautomatically exist in this this table for each mteEventEntry\\nthat has \'set\' set in mteEventActions.\",\"index\":[\"1.3.6.1.2.1.88.1.2.2.1.1\",\"IMPLIED 1.3.6.1.2.1.88.1.4.2.1.1\"],\"name\":\"mteEventSetEntry\",\"objectID\":\"1.3.6.1.2.1.88.1.4.4.1\",\"pid\":\"1.3.6.1.2.1.88.1.4.4\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-write\",\"description\":\"The object identifier from the MIB object to set if\\nmteEventActions has \'set\' set.\\n\\nThis object identifier may be wildcarded by leaving\\nsub-identifiers off the end, in which case\\nnteEventSetObjectWildCard must be \'true\'.\\n\\nIf mteEventSetObject is wildcarded the instance used to set the\\nobject to which it points is the same as the instance from the\\nvalue of mteTriggerValueID that triggered the event.\\n\\nEach instance that fills the wildcard is independent of any\\nadditional instances, that is, wildcarded objects operate\\nas if there were a separate table entry for each instance\\nthat fills the wildcard without having to actually predict\\nall possible instances ahead of time.\\n\\nBad object identifiers or a mismatch between truncating the\\nidentifier and the value of mteSetObjectWildcard\\nresult in operation as one would expect when providing the\\nwrong identifier to a Set operation.  The Set will fail or set\\nthe wrong object.  If the value syntax of the destination\\nobject is not correct, the Set fails with the normal SNMP\\nerror code.\",\"index\":[],\"name\":\"mteEventSetObject\",\"objectID\":\"1.3.6.1.2.1.88.1.4.4.1.1\",\"pid\":\"1.3.6.1.2.1.88.1.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"Control over whether mteEventSetObject is to be treated as\\nfully-specified or wildcarded, with \'true\' indicating wildcard\\nif mteEventActions has \'set\' set.\",\"index\":[],\"name\":\"mteEventSetObjectWildcard\",\"objectID\":\"1.3.6.1.2.1.88.1.4.4.1.2\",\"pid\":\"1.3.6.1.2.1.88.1.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The value to which to set the object at mteEventSetObject\\nif mteEventActions has \'set\' set.\",\"index\":[],\"name\":\"mteEventSetValue\",\"objectID\":\"1.3.6.1.2.1.88.1.4.4.1.3\",\"pid\":\"1.3.6.1.2.1.88.1.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The tag for the target(s) at which to set the object at\\nmteEventSetObject to mteEventSetValue if mteEventActions\\nhas \'set\' set.\\n\\nSystems limited to self management MAY reject a non-zero\\nlength for the value of this object.\\n\\nA length of 0 indicates the local system.  In this case,\\naccess to the objects indicated by mteEventSetObject is under\\nthe security credentials of the requester that set\\nmteTriggerEntryStatus to \'active\'.  Those credentials are the\\ninput parameters for isAccessAllowed from the Architecture for\\nDescribing SNMP Management Frameworks.\\n\\nOtherwise access rights are checked according to the security\\nparameters resulting from the tag.\",\"index\":[],\"name\":\"mteEventSetTargetTag\",\"objectID\":\"1.3.6.1.2.1.88.1.4.4.1.4\",\"pid\":\"1.3.6.1.2.1.88.1.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"The management context in which to set mteEventObjectID.\\nif mteEventActions has \'set\' set.\\n\\nThis may be wildcarded by leaving characters off the end.  To\\nindicate such wildcarding mteEventSetContextNameWildcard must\\nbe \'true\'.\\n\\nIf this context name is wildcarded the value used to complete\\nthe wildcarding of mteTriggerContextName will be appended.\",\"index\":[],\"name\":\"mteEventSetContextName\",\"objectID\":\"1.3.6.1.2.1.88.1.4.4.1.5\",\"pid\":\"1.3.6.1.2.1.88.1.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-write\",\"description\":\"Control for whether mteEventSetContextName is to be treated as\\nfully-specified or wildcarded, with \'true\' indicating wildcard\\nif mteEventActions has \'set\' set.\",\"index\":[],\"name\":\"mteEventSetContextNameWildcard\",\"objectID\":\"1.3.6.1.2.1.88.1.4.4.1.6\",\"pid\":\"1.3.6.1.2.1.88.1.4.4.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"}],\"type\":\"IDENTIFIER\"},{\"access\":\"read-write\",\"description\":\"Control for whether mteEventSetContextName is to be treated as\\nfully-specified or wildcarded, with \'true\' indicating wildcard\\nif mteEventActions has \'set\' set.\",\"index\":[],\"name\":\"dismanEventMIBNotificationPrefix\",\"objectID\":\"1.3.6.1.2.1.88.2\",\"pid\":\"1.3.6.1.2.1.88\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-write\",\"description\":\"Control for whether mteEventSetContextName is to be treated as\\nfully-specified or wildcarded, with \'true\' indicating wildcard\\nif mteEventActions has \'set\' set.\",\"index\":[],\"name\":\"dismanEventMIBNotifications\",\"objectID\":\"1.3.6.1.2.1.88.2.0\",\"pid\":\"1.3.6.1.2.1.88.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"mteTriggerFired\",\"objectID\":\"1.3.6.1.2.1.88.2.0.1\",\"pid\":\"1.3.6.1.2.1.88.2.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"mteTriggerRising\",\"objectID\":\"1.3.6.1.2.1.88.2.0.2\",\"pid\":\"1.3.6.1.2.1.88.2.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"mteTriggerFalling\",\"objectID\":\"1.3.6.1.2.1.88.2.0.3\",\"pid\":\"1.3.6.1.2.1.88.2.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"mteTriggerFailure\",\"objectID\":\"1.3.6.1.2.1.88.2.0.4\",\"pid\":\"1.3.6.1.2.1.88.2.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"mteEventSetFailure\",\"objectID\":\"1.3.6.1.2.1.88.2.0.5\",\"pid\":\"1.3.6.1.2.1.88.2.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"},{\"access\":\"read-write\",\"description\":\"Control for whether mteEventSetContextName is to be treated as\\nfully-specified or wildcarded, with \'true\' indicating wildcard\\nif mteEventActions has \'set\' set.\",\"index\":[],\"name\":\"dismanEventMIBNotificationObjects\",\"objectID\":\"1.3.6.1.2.1.88.2.1\",\"pid\":\"1.3.6.1.2.1.88.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"accessible-for-notify\",\"description\":\"The name of the trigger causing the notification.\",\"index\":[],\"name\":\"mteHotTrigger\",\"objectID\":\"1.3.6.1.2.1.88.2.1.1\",\"pid\":\"1.3.6.1.2.1.88.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The SNMP Target MIB\'s snmpTargetAddrName related to the\\nnotification.\",\"index\":[],\"name\":\"mteHotTargetName\",\"objectID\":\"1.3.6.1.2.1.88.2.1.2\",\"pid\":\"1.3.6.1.2.1.88.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The context name related to the notification.  This MUST be as\\nfully-qualified as possible, including filling in wildcard\\ninformation determined in processing.\",\"index\":[],\"name\":\"mteHotContextName\",\"objectID\":\"1.3.6.1.2.1.88.2.1.3\",\"pid\":\"1.3.6.1.2.1.88.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The object identifier of the destination object related to the\\nnotification.  This MUST be as fully-qualified as possible,\\nincluding filling in wildcard information determined in\\nprocessing.\\n\\nFor a trigger-related notification this is from\\nmteTriggerValueID.\\n\\nFor a set failure this is from mteEventSetObject.\",\"index\":[],\"name\":\"mteHotOID\",\"objectID\":\"1.3.6.1.2.1.88.2.1.4\",\"pid\":\"1.3.6.1.2.1.88.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The value of the object at mteTriggerValueID when a\\ntrigger fired.\",\"index\":[],\"name\":\"mteHotValue\",\"objectID\":\"1.3.6.1.2.1.88.2.1.5\",\"pid\":\"1.3.6.1.2.1.88.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"mteFailedReason\",\"objectID\":\"1.3.6.1.2.1.88.2.1.6\",\"pid\":\"1.3.6.1.2.1.88.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"},{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"dismanEventMIBConformance\",\"objectID\":\"1.3.6.1.2.1.88.3\",\"pid\":\"1.3.6.1.2.1.88\",\"status\":\"current\",\"subTree\":[{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"dismanEventMIBCompliances\",\"objectID\":\"1.3.6.1.2.1.88.3.1\",\"pid\":\"1.3.6.1.2.1.88.3\",\"status\":\"current\",\"subTree\":[{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"dismanEventMIBCompliance\",\"objectID\":\"1.3.6.1.2.1.88.3.1.1\",\"pid\":\"1.3.6.1.2.1.88.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"},{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"dismanEventMIBGroups\",\"objectID\":\"1.3.6.1.2.1.88.3.2\",\"pid\":\"1.3.6.1.2.1.88.3\",\"status\":\"current\",\"subTree\":[{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"dismanEventResourceGroup\",\"objectID\":\"1.3.6.1.2.1.88.3.2.1\",\"pid\":\"1.3.6.1.2.1.88.3.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"dismanEventTriggerGroup\",\"objectID\":\"1.3.6.1.2.1.88.3.2.2\",\"pid\":\"1.3.6.1.2.1.88.3.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"dismanEventObjectsGroup\",\"objectID\":\"1.3.6.1.2.1.88.3.2.3\",\"pid\":\"1.3.6.1.2.1.88.3.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"dismanEventEventGroup\",\"objectID\":\"1.3.6.1.2.1.88.3.2.4\",\"pid\":\"1.3.6.1.2.1.88.3.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"dismanEventNotificationObjectGroup\",\"objectID\":\"1.3.6.1.2.1.88.3.2.5\",\"pid\":\"1.3.6.1.2.1.88.3.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"accessible-for-notify\",\"description\":\"The reason for the failure of an attempt to check for a\\ntrigger condition or set an object in response to an event.\",\"index\":[],\"name\":\"dismanEventNotificationGroup\",\"objectID\":\"1.3.6.1.2.1.88.3.2.6\",\"pid\":\"1.3.6.1.2.1.88.3.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"Information about a single trigger\'s delta sampling.  Entries\\nautomatically exist in this this table for each mteTriggerEntry\\nthat has mteTriggerSampleType set to \'deltaValue\'.\",\"index\":[\"1.3.6.1.2.1.88.1.2.2.1.1\",\"IMPLIED 1.3.6.1.2.1.88.1.2.2.1.2\"],\"name\":\"sysUpTimeInstance\",\"objectID\":\"1.3.6.1.2.1.1.3.0\",\"pid\":\"1.3.6.1.2.1.1.3\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}]}');
INSERT INTO `snmp_mib`(`id`, `name`, `file_name`, `content`, `models`, `remark`, `update_by`, `update_at`, `tree`) VALUES (5, 'DISMAN-SCHEDULE-MIB', 'DISMAN-SCHEDULE-MIB.txt', , '', '', 1, '2021-09-29 11:55:55', '{\"DISMAN-SCHEDULE-MIB\":[{\"index\":[],\"name\":\"schedMIB\",\"objectID\":\"1.3.6.1.2.1.63\",\"pid\":\"1.3.6.1.2.1\",\"subTree\":[{\"index\":[],\"name\":\"schedObjects\",\"objectID\":\"1.3.6.1.2.1.63.1\",\"pid\":\"1.3.6.1.2.1.63\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"The local time used by the scheduler.  Schedules which\\nrefer to calendar time will use the local time indicated\\nby this object.  An implementation MUST return all 11 bytes\\nof the DateAndTime textual-convention so that a manager\\nmay retrieve the offset from GMT time.\",\"index\":[],\"name\":\"schedLocalTime\",\"objectID\":\"1.3.6.1.2.1.63.1.1\",\"pid\":\"1.3.6.1.2.1.63.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"This table defines scheduled actions triggered by\\nSNMP set operations.\",\"index\":[],\"name\":\"schedTable\",\"objectID\":\"1.3.6.1.2.1.63.1.2\",\"pid\":\"1.3.6.1.2.1.63.1\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"An entry describing a particular scheduled action.\\n\\nUnless noted otherwise, writable objects of this row\\ncan be modified independent of the current value of\\nschedRowStatus, schedAdminStatus and schedOperStatus.\\nIn particular, it is legal to modify schedInterval\\nand the objects in the schedCalendarGroup when\\nschedRowStatus is active and schedAdminStatus and\\nschedOperStatus are both enabled.\",\"index\":[\"1.3.6.1.2.1.63.1.2.1.1\",\"1.3.6.1.2.1.63.1.2.1.2\"],\"name\":\"schedEntry\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1\",\"pid\":\"1.3.6.1.2.1.63.1.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"not-accessible\",\"description\":\"The owner of this scheduling entry.  The exact semantics of\\nthis string are subject to the security policy defined by\\n\\nthe security administrator.\",\"index\":[],\"name\":\"schedOwner\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.1\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"not-accessible\",\"description\":\"The locally-unique, administratively assigned name for this\\nscheduling entry.  This object allows a schedOwner to have\\nmultiple entries in the schedTable.\",\"index\":[],\"name\":\"schedName\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.2\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The human readable description of the purpose of this\\nscheduling entry.\",\"index\":[],\"name\":\"schedDescr\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.3\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The number of seconds between two action invocations of\\na periodic scheduler.  Implementations must guarantee\\nthat action invocations will not occur before at least\\nschedInterval seconds have passed.\\n\\nThe scheduler must ignore all periodic schedules that\\nhave a schedInterval value of 0.  A periodic schedule\\nwith a scheduling interval of 0 seconds will therefore\\nnever invoke an action.\\n\\nImplementations may be forced to delay invocations in the\\nface of local constraints.  A scheduled management function\\nshould therefore not rely on the accuracy provided by the\\nscheduler implementation.\\n\\nNote that implementations which maintain a list of pending\\nactivations must re-calculate them when this object is\\nchanged.\",\"index\":[],\"name\":\"schedInterval\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.4\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The set of weekdays on which the scheduled action should\\ntake place.  Setting multiple bits will include several\\nweekdays in the set of possible weekdays for this schedule.\\nSetting all bits will cause the scheduler to ignore the\\nweekday.\\n\\nNote that implementations which maintain a list of pending\\nactivations must re-calculate them when this object is\\nchanged.\",\"index\":[],\"name\":\"schedWeekDay\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.5\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"BITS\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The set of months during which the scheduled action should\\ntake place.  Setting multiple bits will include several\\nmonths in the set of possible months for this schedule.\\n\\nSetting all bits will cause the scheduler to ignore the\\nmonth.\\n\\nNote that implementations which maintain a list of pending\\nactivations must re-calculate them when this object is\\nchanged.\",\"index\":[],\"name\":\"schedMonth\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.6\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"BITS\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The set of days in a month on which a scheduled action\\nshould take place.  There are two sets of bits one can\\nuse to define the day within a month:\\n\\nEnumerations starting with the letter \'d\' indicate a\\nday in a month relative to the first day of a month.\\nThe first day of the month can therefore be specified\\nby setting the bit d1(0) and d31(30) means the last\\nday of a month with 31 days.\\n\\nEnumerations starting with the letter \'r\' indicate a\\nday in a month in reverse order, relative to the last\\nday of a month.  The last day in the month can therefore\\nbe specified by setting the bit r1(31) and r31(61) means\\nthe first day of a month with 31 days.\\n\\nSetting multiple bits will include several days in the set\\nof possible days for this schedule.  Setting all bits will\\ncause the scheduler to ignore the day within a month.\\n\\nSetting all bits starting with the letter \'d\' or the\\nletter \'r\' will also cause the scheduler to ignore the\\nday within a month.\\n\\nNote that implementations which maintain a list of pending\\nactivations must re-calculate them when this object is\\nchanged.\",\"index\":[],\"name\":\"schedDay\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.7\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"BITS\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The set of hours within a day during which the scheduled\\naction should take place.\\n\\nNote that implementations which maintain a list of pending\\nactivations must re-calculate them when this object is\\nchanged.\",\"index\":[],\"name\":\"schedHour\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.8\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"BITS\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The set of minutes within an hour when the scheduled action\\nshould take place.\\n\\nNote that implementations which maintain a list of pending\\nactivations must re-calculate them when this object is\\nchanged.\",\"index\":[],\"name\":\"schedMinute\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.9\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"BITS\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The context which contains the local MIB variable pointed\\nto by schedVariable.\",\"index\":[],\"name\":\"schedContextName\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.10\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"An object identifier pointing to a local MIB variable\\nwhich resolves to an ASN.1 primitive type of INTEGER.\",\"index\":[],\"name\":\"schedVariable\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.11\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OBJECT IDENTIFIER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The value which is written to the MIB object pointed to by\\nschedVariable when the scheduler invokes an action.  The\\nimplementation shall enforce the use of access control\\nrules when performing the set operation on schedVariable.\\nThis is accomplished by calling the isAccessAllowed abstract\\nservice interface as defined in RFC 2571.\\n\\nNote that an implementation may choose to issue an SNMP Set\\nmessage to the SNMP engine and leave the access control\\ndecision to the normal message processing procedure.\",\"index\":[],\"name\":\"schedValue\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.12\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The type of this schedule.  The value periodic(1) indicates\\nthat this entry specifies a periodic schedule.  A periodic\\nschedule is defined by the value of schedInterval.  The\\nvalues of schedWeekDay, schedMonth, schedDay, schedHour\\nand schedMinute are ignored.\\n\\nThe value calendar(2) indicates that this entry describes a\\ncalendar schedule.  A calendar schedule is defined by the\\nvalues of schedWeekDay, schedMonth, schedDay, schedHour and\\nschedMinute.  The value of schedInterval is ignored.  A\\ncalendar schedule will trigger on all local times that\\nsatisfy the bits set in schedWeekDay, schedMonth, schedDay,\\nschedHour and schedMinute.\\n\\nThe value oneshot(3) indicates that this entry describes a\\none-shot schedule.  A one-shot schedule is similar to a\\ncalendar schedule with the additional feature that it\\ndisables itself by changing in the `finished\'\\nschedOperStatus once the schedule triggers an action.\\n\\nNote that implementations which maintain a list of pending\\nactivations must re-calculate them when this object is\\nchanged.\",\"index\":[],\"name\":\"schedType\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.13\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The desired state of the schedule.\",\"index\":[],\"name\":\"schedAdminStatus\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.14\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The current operational state of this schedule.  The state\\nenabled(1) indicates this entry is active and that the\\nscheduler will invoke actions at appropriate times.  The\\ndisabled(2) state indicates that this entry is currently\\ninactive and ignored by the scheduler.  The finished(3)\\nstate indicates that the schedule has ended.  Schedules\\nin the finished(3) state are ignored by the scheduler.\\nA one-shot schedule enters the finished(3) state when it\\ndeactivates itself.\\n\\nNote that the operational state must not be enabled(1)\\nwhen the schedRowStatus is not active.\",\"index\":[],\"name\":\"schedOperStatus\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.15\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This variable counts the number of failures while invoking\\nthe scheduled action.  This counter at most increments once\\nfor a triggered action.\",\"index\":[],\"name\":\"schedFailures\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.16\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The most recent error that occurred during the invocation of\\na scheduled action.  The value noError(0) is returned\\nif no errors have occurred yet.\",\"index\":[],\"name\":\"schedLastFailure\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.17\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"The date and time when the most recent failure occurred.\\n\\nThe value \'0000000000000000\'H is returned if no failure\\noccurred since the last re-initialization of the scheduler.\",\"index\":[],\"name\":\"schedLastFailed\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.18\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"OCTET STRING\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"This object defines whether this scheduled action is kept\\nin volatile storage and lost upon reboot or if this row is\\nbacked up by non-volatile or permanent storage.\\n\\nConceptual rows having the value `permanent\' must allow\\nwrite access to the columnar objects schedDescr,\\nschedInterval, schedContextName, schedVariable, schedValue,\\nand schedAdminStatus.  If an implementation supports the\\nschedCalendarGroup, write access must be also allowed to\\nthe columnar objects schedWeekDay, schedMonth, schedDay,\\nschedHour, schedMinute.\",\"index\":[],\"name\":\"schedStorageType\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.19\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-create\",\"description\":\"The status of this scheduled action.  A control that allows\\nentries to be added and removed from this table.\\n\\nNote that the operational state must change to enabled\\nwhen the administrative state is enabled and the row\\nstatus changes to active(1).\\n\\nAttempts to destroy(6) a row or to set a row\\nnotInService(2) while the operational state is enabled\\nresult in inconsistentValue errors.\\n\\nThe value of this object has no effect on whether other\\nobjects in this conceptual row can be modified.\",\"index\":[],\"name\":\"schedRowStatus\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.20\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This variable counts the number of attempts (either\\nsuccessful or failed) to invoke the scheduled action.\",\"index\":[],\"name\":\"schedTriggers\",\"objectID\":\"1.3.6.1.2.1.63.1.2.1.21\",\"pid\":\"1.3.6.1.2.1.63.1.2.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"SEQUENCE\",\"type\":\"ENTRY\"}],\"syntax\":\"SEQUENCE\",\"type\":\"TABLE\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"schedNotifications\",\"objectID\":\"1.3.6.1.2.1.63.2\",\"pid\":\"1.3.6.1.2.1.63\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"This variable counts the number of attempts (either\\nsuccessful or failed) to invoke the scheduled action.\",\"index\":[],\"name\":\"schedTraps\",\"objectID\":\"1.3.6.1.2.1.63.2.0\",\"pid\":\"1.3.6.1.2.1.63.2\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"This variable counts the number of attempts (either\\nsuccessful or failed) to invoke the scheduled action.\",\"index\":[],\"name\":\"schedActionFailure\",\"objectID\":\"1.3.6.1.2.1.63.2.0.1\",\"pid\":\"1.3.6.1.2.1.63.2.0\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"type\":\"IDENTIFIER\"},{\"index\":[],\"name\":\"schedConformance\",\"objectID\":\"1.3.6.1.2.1.63.3\",\"pid\":\"1.3.6.1.2.1.63\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"This variable counts the number of attempts (either\\nsuccessful or failed) to invoke the scheduled action.\",\"index\":[],\"name\":\"schedCompliances\",\"objectID\":\"1.3.6.1.2.1.63.3.1\",\"pid\":\"1.3.6.1.2.1.63.3\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"This variable counts the number of attempts (either\\nsuccessful or failed) to invoke the scheduled action.\",\"index\":[],\"name\":\"schedCompliance2\",\"objectID\":\"1.3.6.1.2.1.63.3.1.2\",\"pid\":\"1.3.6.1.2.1.63.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This variable counts the number of attempts (either\\nsuccessful or failed) to invoke the scheduled action.\",\"index\":[],\"name\":\"schedCompliance\",\"objectID\":\"1.3.6.1.2.1.63.3.1.1\",\"pid\":\"1.3.6.1.2.1.63.3.1\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"},{\"access\":\"read-only\",\"description\":\"This variable counts the number of attempts (either\\nsuccessful or failed) to invoke the scheduled action.\",\"index\":[],\"name\":\"schedGroups\",\"objectID\":\"1.3.6.1.2.1.63.3.2\",\"pid\":\"1.3.6.1.2.1.63.3\",\"status\":\"current\",\"subTree\":[{\"access\":\"read-only\",\"description\":\"This variable counts the number of attempts (either\\nsuccessful or failed) to invoke the scheduled action.\",\"index\":[],\"name\":\"schedGroup2\",\"objectID\":\"1.3.6.1.2.1.63.3.2.4\",\"pid\":\"1.3.6.1.2.1.63.3.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This variable counts the number of attempts (either\\nsuccessful or failed) to invoke the scheduled action.\",\"index\":[],\"name\":\"schedCalendarGroup\",\"objectID\":\"1.3.6.1.2.1.63.3.2.2\",\"pid\":\"1.3.6.1.2.1.63.3.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This variable counts the number of attempts (either\\nsuccessful or failed) to invoke the scheduled action.\",\"index\":[],\"name\":\"schedNotificationsGroup\",\"objectID\":\"1.3.6.1.2.1.63.3.2.3\",\"pid\":\"1.3.6.1.2.1.63.3.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"},{\"access\":\"read-only\",\"description\":\"This variable counts the number of attempts (either\\nsuccessful or failed) to invoke the scheduled action.\",\"index\":[],\"name\":\"schedGroup\",\"objectID\":\"1.3.6.1.2.1.63.3.2.1\",\"pid\":\"1.3.6.1.2.1.63.3.2\",\"status\":\"current\",\"subTree\":[],\"syntax\":\"INTEGER\",\"type\":\"OBJECT\"}],\"syntax\":\"INTEGER\",\"type\":\"IDENTIFIER\"}],\"type\":\"IDENTIFIER\"}],\"type\":\"OBJECT\"}]}');
